def _hoy() -> str:
    # zona Argentina (UTC-3) sin depender de tz del server
    return (_dt.datetime.utcnow() - _dt.timedelta(hours=3)).strftime("%Y-%m-%d")


# --- Resumen VACÍO: misma forma que espera el dashboard, todo en cero ---
def resumen_vacio() -> dict:
    h = _hoy()
    ceros_int = ["ordenes", "unidades", "reemb_cantidad", "reemb_monto", "reemb_despachados",
                 "ventas_recompras", "ventas_periodo", "meli_ventas", "meli_unidades", "tot_ordenes"]
    ceros_float = ["facturado", "cobrado", "costo_prod", "envio", "comision", "impuestos",
                   "com_plataforma", "com_pago", "fullfilment", "envios", "envio_prom", "oper_monto",
                   "costos_extra", "reemb_perdida", "gan_por_venta", "cpa", "publi_ars",
                   "publi_cuenta", "ganancia", "margen", "roas", "roas_be", "ticket",
                   "tasa_recompra", "facturacion_recompras",
                   "meli_facturado", "meli_cobrado", "meli_comision", "meli_costo", "meli_ganancia",
                   "meli_rent", "meli_fullfilment", "meli_aov", "meli_roas",
                   "tot_facturado", "tot_ganancia", "tot_margen", "tot_costo", "tot_fullfilment",
                   "tot_gan_por_venta", "tot_aov"]
    r = {"fecha": h, "desde": h, "hasta": h, "actualizado": h,
         "moneda": "ARS", "dolar": 1200.0}
    for k in ceros_int:
        r[k] = 0
    for k in ceros_float:
        r[k] = 0.0
    return r


def _blob_vacio() -> dict:
    return {"raw": resumen_vacio(), "prod": [], "ords": []}


# ---------------- Datos reales de Shopify → dashboard ----------------
def _shopify_orders(shop, token, desde, hasta, deadline=None, max_pages=80, timeout=30):
    """Trae los pedidos de Shopify del período (paginado por Link header).
    deadline/max_pages/timeout: topes opcionales para que un caller pesado (ej Insertar SKU) NO se cuelgue;
    por default (None/80/30) se comporta EXACTAMENTE como antes para los demás usos."""
    out = []
    url = "https://%s/admin/api/2026-07/orders.json" % shop
    params = {"status": "any", "limit": 250,
              "created_at_min": desde + "T00:00:00-03:00",
              "created_at_max": hasta + "T23:59:59-03:00",
              "fields": "id,order_number,name,total_price,current_total_price,financial_status,cancelled_at,line_items,refunds,created_at,shipping_lines,shipping_address"}
    headers = {"X-Shopify-Access-Token": token}
    import time as _tsleep
    for _ in range(max_pages):
        if deadline and _tsleep.time() > deadline:     # se agotó el presupuesto de tiempo → corto con lo que tengo
            break
        r = requests.get(url, headers=headers, params=params, timeout=timeout)
        if r.status_code == 429 or r.status_code >= 500:   # límite/servidor: reintenta la MISMA página, NO corta
            _tsleep.sleep(float(r.headers.get("Retry-After", 1)) + 0.3)
            continue
        if r.status_code != 200:
            break
        out.extend(r.json().get("orders", []))
        link = r.headers.get("Link", "") or r.headers.get("link", "")
        nxt = None
        for part in link.split(","):
            if 'rel="next"' in part and "<" in part and ">" in part:
                nxt = part[part.find("<") + 1:part.find(">")]
        if not nxt:
            break
        url = nxt
        params = None
    return out


_MP_COST_CACHE = {}

# ---- Congelado del histórico de MercadoPago -------------------------------------------------
# Antes de cambiar de cuenta de MP, se "congela" todo lo cobrado hasta FREEZE_END en un snapshot
# (DATA_DIR/mp_freeze.json, en el disco persistente). Desde ahí en adelante, cualquier fecha
# <= FREEZE_END se sirve del snapshot y sólo lo posterior se pide en vivo a MP. Así el dashboard
# mantiene la ganancia vieja aunque se conecte otra cuenta de MercadoPago.
# Si el snapshot NO existe para un usuario, todo funciona EXACTAMENTE como antes (todo en vivo).
FREEZE_END = "2026-08-14"          # último día que se sirve desde el congelado
_DIA_POST_FREEZE = "2026-08-15"    # primer día que se pide en vivo (FREEZE_END + 1)
_MP_FREEZE_FILE = DATA_DIR / "mp_freeze.json"
_MP_FREEZE_CACHE = None            # {email: [pago_crudo, ...]}


def _mp_freeze_all() -> dict:
    global _MP_FREEZE_CACHE
    if _MP_FREEZE_CACHE is None:
        try:
            _MP_FREEZE_CACHE = _json.loads(_MP_FREEZE_FILE.read_text(encoding="utf-8"))
        except Exception:
            _MP_FREEZE_CACHE = {}
    return _MP_FREEZE_CACHE


def _mp_freeze_slice(fr, desde, tope):
    """Pagos congelados cuyo día de date_approved (-03) cae en [desde, tope]."""
    if not fr or desde > tope:
        return []
    return [p for p in fr if desde <= (p.get("date_approved") or "")[:10] <= tope]


MP_SWITCH_FILE = DATA_DIR / "mp_switch.json"   # {email: "YYYY-MM-DD"} → desde ese día (00:00) se usa el MP NUEVO
_MP_SWITCH_CACHE = None


def _mp_switch() -> dict:
    global _MP_SWITCH_CACHE
    if _MP_SWITCH_CACHE is None:
        try:
            _MP_SWITCH_CACHE = _json.loads(MP_SWITCH_FILE.read_text(encoding="utf-8"))
        except Exception:
            _MP_SWITCH_CACHE = {}
    return _MP_SWITCH_CACHE


def _mp_save_switch(d):
    global _MP_SWITCH_CACHE
    _MP_SWITCH_CACHE = d
    MP_SWITCH_FILE.write_text(_json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")


def _dia_post(s):
    try:
        return (_dt.date.fromisoformat(s) + _dt.timedelta(days=1)).isoformat()
    except Exception:
        return s


def _dia_ant(s):
    try:
        return (_dt.date.fromisoformat(s) - _dt.timedelta(days=1)).isoformat()
    except Exception:
        return s


def _mp_freeze_end(email):
    """Último día (inclusive) que se sirve del congelado para este email. None si no hay congelado.
    Si hay una fecha de cambio de MP guardada → el congelado cubre hasta el día ANTERIOR a esa fecha."""
    sw = _mp_switch().get(email)
    if sw:
        return _dia_ant(sw)
    if _mp_freeze_all().get(email):
        return FREEZE_END
    return None


TIENDA_PCT = 1.0        # comisión de tienda (Shopify/TN): 1% fijo por venta, no editable
IIBB_PCT = 3.5          # Ingresos Brutos: 3,5% fijo por venta, no editable
FULFILLMENT_ORDEN = 800  # costo de fulfillment por pedido (fijo)
INSUMOS_ORDEN = 200      # costo de insumos/packaging por pedido (fijo)
OPER_ORDEN = FULFILLMENT_ORDEN + INSUMOS_ORDEN  # 1000/pedido: fulfillment + insumos (aparte del envío)

# === Costo de envío REAL por zona (Andreani, cuenta VisionPure, origen Suc. Merlo, CON descuento) ===
# Cotizado 2026-08-15 en pymes.andreani.com. 4 zonas de tarifa. sucursal / domicilio en $.
ENVIO_ZONAS = {
    "amba":    {"sucursal": 4530, "domicilio": 7115},   # CABA + GBA + La Plata
    "centro":  {"sucursal": 6082, "domicilio": 8001},   # Bs As interior, Córdoba, Santa Fe, E.Ríos, La Pampa
    "cuyo":    {"sucursal": 6603, "domicilio": 8717},    # Cuyo, Norte, NEA, Neuquén, Río Negro
    "extremo": {"sucursal": 7101, "domicilio": 9189},    # Salta, Jujuy, Chubut, Santa Cruz, T. del Fuego
}
# fallback (promedio ponderado nacional) si no se puede determinar la zona
ENVIO_DOMICILIO = 7805
ENVIO_SUCURSAL = 5539

_ENV_ACC = str.maketrans("áéíóúüàèìòùÁÉÍÓÚÜÑñ", "aeiouuaeiouAEIOUUNn")
def _env_norm(s):
    return str(s or "").translate(_ENV_ACC).lower().strip()

# provincia (nombre normalizado) -> zona. Buenos Aires se resuelve por CP aparte.
_PROV_ZONA = {
    "capital federal": "amba", "ciudad autonoma de buenos aires": "amba", "caba": "amba",
    "ciudad de buenos aires": "amba", "capital": "amba", "c.a.b.a.": "amba",
    "cordoba": "centro", "santa fe": "centro", "entre rios": "centro", "la pampa": "centro",
    "mendoza": "cuyo", "san juan": "cuyo", "san luis": "cuyo", "tucuman": "cuyo",
    "santiago del estero": "cuyo", "catamarca": "cuyo", "la rioja": "cuyo",
    "misiones": "cuyo", "corrientes": "cuyo", "chaco": "cuyo", "formosa": "cuyo",
    "neuquen": "cuyo", "rio negro": "cuyo",
    "salta": "extremo", "jujuy": "extremo", "chubut": "extremo",
    "santa cruz": "extremo", "tierra del fuego": "extremo",
}
# código ISO 3166-2 de 1 letra (TN a veces manda 'C','X'...). 'B' = Buenos Aires → por CP.
_ISO_ZONA = {
    "C": "amba", "X": "centro", "S": "centro", "E": "centro", "L": "centro",
    "M": "cuyo", "J": "cuyo", "D": "cuyo", "T": "cuyo", "G": "cuyo", "K": "cuyo",
    "F": "cuyo", "N": "cuyo", "W": "cuyo", "H": "cuyo", "P": "cuyo", "Q": "cuyo", "R": "cuyo",
    "A": "extremo", "Y": "extremo", "U": "extremo", "Z": "extremo", "V": "extremo",
}

def _prov_cp(o):
    """Provincia + CP del pedido, sirve tanto para la forma Shopify (shipping_address dict con
    'province'/'zip') como para el pedido nativo de Tiendanube (varias ubicaciones posibles)."""
    for src in (o.get("shipping_address"), o.get("billing_address")):
        if isinstance(src, dict):
            prov = src.get("province") or src.get("state") or ""
            cp = src.get("zipcode") or src.get("zip") or src.get("postal_code") or ""
            if prov or cp:
                return prov, cp
    prov = o.get("shipping_province") or o.get("province") or ""
    cp = o.get("shipping_zipcode") or o.get("shipping_zip") or o.get("zip") or ""
    return prov, cp

def _envio_zona(o) -> str:
    prov, cp = _prov_cp(o)
    cp = "".join(ch for ch in str(cp) if ch.isdigit())
    pn = _env_norm(prov)
    code = str(prov).strip().upper()
    # CABA (nombre en cualquier variante)
    if ("capital federal" in pn or "autonoma de buenos aires" in pn or "ciudad de buenos aires" in pn
            or pn in ("caba", "capital", "c.a.b.a.") or code == "C"):
        return "amba"
    # Buenos Aires PROVINCIA → GBA (CP 1xxx) = AMBA ; interior = Centro
    if code == "B" or "buenos aires" in pn or pn in ("bs as", "bsas", "pba"):
        return "amba" if cp[:1] == "1" else "centro"
    # código ISO de 1 letra
    if len(code) == 1 and code in _ISO_ZONA:
        return _ISO_ZONA[code]
    # nombre de provincia por coincidencia (soporta nombres oficiales largos)
    for k, z in _PROV_ZONA.items():
        if k in ("capital federal", "ciudad autonoma de buenos aires", "caba",
                 "ciudad de buenos aires", "capital", "c.a.b.a."):
            continue
        if k in pn:
            return z
    return "amba" if cp[:1] == "1" else "centro"   # último fallback por CP

def _txt_es_sucursal(txt) -> bool:
    """ÚNICA fuente de verdad para clasificar sucursal por el TEXTO del método de envío.
    Regla conservadora: por DEFECTO domicilio. Sucursal solo con señal explícita como PALABRA
    ENTERA (no substring: 'hop' NO cuenta dentro de 'shop'). Si el texto dice 'domicilio' →
    NUNCA sucursal. Así jamás flipeamos un domicilio a sucursal."""
    import re
    txt = (txt or "").lower()
    if not txt.strip():
        return False
    if re.search(r"\b(a\s+)?domicilio\b|\bhome\s*deliver|\benv[ií]o\s+a\s+casa\b", txt):
        return False
    return bool(re.search(
        r"\bsucursal\b|\bpick\s*-?\s*up\b|\bpickup\b|\bretir[oa]\b|\bagencia\b|"
        r"\bpunto\s+(de\s+)?retiro\b|\bpunto\s+andreani\b|\bhop\b|\bcorreo\s+arg\w*\s+sucursal\b",
        txt))


def _envio_suc(o) -> bool:
    """Costo: usa la MISMA regla que el export. Pickup explícito de TN, o el texto del método."""
    if o.get("shipping_pickup_type") == "pickup":
        return True
    txt = " ".join(((s.get("title") or "") + " " + (s.get("code") or "")) for s in (o.get("shipping_lines") or []))
    txt += " " + (o.get("shipping_option") or "")   # TN manda el método acá ("Envío a domicilio"/"Punto de retiro")
    return _txt_es_sucursal(txt)

def _envio_costo(o) -> int:
    """Costo de envío REAL por zona Andreani (cuenta VisionPure, con descuento), según
    provincia/CP del pedido y si es a sucursal o domicilio. Cubre Shopify y Tiendanube.
    Fallback cuando el pedido todavía no está en Envialo (costo real)."""
    z = ENVIO_ZONAS.get(_envio_zona(o)) or {"sucursal": ENVIO_SUCURSAL, "domicilio": ENVIO_DOMICILIO}
    return z["sucursal"] if _envio_suc(o) else z["domicilio"]


ENVIALO_BASE = "https://www.envialo.com.ar/api/v1"
ENVIALO_KEYS = DATA_DIR / "envialo_keys.json"   # API key de Envialo por usuario (persistente)
_ENVIALO_CACHE = {}   # email -> (ts, {nº pedido: costo})


def _envialo_keys() -> dict:
    try:
        return _json.loads(ENVIALO_KEYS.read_text(encoding="utf-8"))
    except Exception:
        return {}


def _envialo_save_key(email, key) -> None:
    d = _envialo_keys()
    d[str(email)] = key
    ENVIALO_KEYS.write_text(_json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")


def _envialo_key_de(email):
    import os
    return (_envialo_keys().get(email) or os.getenv("ENVIALO_API_KEY", "")) if email else ""


def _envialo_fetch(key: str) -> dict:
    """{nº de pedido → costo REAL de envío} pegándole a Envialo con esa API key."""
    out = {}
    try:
        for pg in range(40):
            r = requests.get(ENVIALO_BASE + "/orders", headers={"X-API-Key": key},
                             params={"page": pg, "limit": 50}, timeout=30)
            if r.status_code != 200:
                break
            j = r.json()
            for o in j.get("orders", []):
                n = str(o.get("number") or "").strip()
                sc = o.get("shipping_cost")
                if n and sc not in (None, "", 0):
                    try:
                        out[n] = float(sc)
                    except (TypeError, ValueError):
                        pass
            if not j.get("hasMore"):
                break
    except Exception:
        pass
    return out


def _envialo_costos(email=None):
    """{nº de pedido → costo REAL de envío} desde la cuenta Envialo de ESE usuario.
    Vacío si no conectó su API key. Cache 5 min por usuario."""
    import time as _t
    key = _envialo_key_de(email)
    if not key:
        return {}
    c = _ENVIALO_CACHE.get(email)
    if c and (_t.time() - c[0] < 300):
        return c[1]
    out = _envialo_fetch(key)
    _ENVIALO_CACHE[email] = (_t.time(), out)
    return out


@app.get("/envialo/estado")
def envialo_estado():
    email = _user_actual()
    return jsonify({"ok": True, "conectado": bool(email and email in _envialo_keys())})


@app.post("/envialo/conectar")
@limiter.limit("20 per hour")
def envialo_conectar():
    """Guarda la API key de Envialo del usuario. Valida pegándole una vez a la API."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "error": "Tenés que iniciar sesión."}), 401
    data = request.get_json(silent=True) or request.form
    key = (data.get("api_key", "") or "").strip()
    if not key:
        return jsonify({"ok": False, "error": "Pegá tu API key de Envialo."}), 400
    try:
        r = requests.get(ENVIALO_BASE + "/orders", headers={"X-API-Key": key},
                         params={"page": 0, "limit": 1}, timeout=25)
        if r.status_code in (401, 403):
            return jsonify({"ok": False, "error": "La API key no es válida (Envialo la rechazó)."}), 400
        if r.status_code != 200:
            return jsonify({"ok": False, "error": "Envialo no respondió bien. Probá de nuevo."}), 400
    except Exception:
        return jsonify({"ok": False, "error": "No pudimos conectar con Envialo. Probá de nuevo."}), 502
    _envialo_save_key(email, key)
    _ENVIALO_CACHE.pop(email, None)
    return jsonify({"ok": True})


@app.get("/desconectar-envialo")
def desconectar_envialo():
    email = _user_actual()
    if email:
        d = _envialo_keys()
        d.pop(email, None)
        ENVIALO_KEYS.write_text(_json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")
        _ENVIALO_CACHE.pop(email, None)
    return redirect("/?integ=1")


def _mp_costos(email, desde, hasta):
    """Costos REALES de MercadoPago del período (de la cuenta MP conectada del usuario).
    costo real por pago = transaction_amount − net_received_amount (incluye comisión +
    financiación de cuotas + IVA, todo lo que MP realmente te sacó).
    Devuelve montos y % separando 1 pago (al instante) de cuotas (3 sin interés). None si no hay MP."""
    import os, time as _t
    tk = _mp_tokens().get(email)
    token = tk.get("access_token") if tk else None
    fr = _mp_freeze_all().get(email)
    if not token and not fr:
        return None
    key = (email, desde, hasta)
    c = _MP_COST_CACHE.get(key)
    if c and (_t.time() - c[0] < 300):
        return c[1]
    # Histórico (<= FREEZE_END) del congelado; nuevo (> FREEZE_END) en vivo desde MP.
    if fr:
        _fe = _mp_freeze_end(email) or FREEZE_END
        _live_ini = _dia_post(_fe) if desde <= _fe else desde
        _run_live = hasta > _fe
        _frozen = _mp_freeze_slice(fr, desde, min(hasta, _fe))
    else:
        _live_ini = desde; _run_live = True; _frozen = []
    ini = _live_ini + "T00:00:00.000-03:00"
    fin = hasta + "T23:59:59.999-03:00"
    vol1 = cost1 = volc = costc = 0.0
    n1 = nc = 0
    offset = 0
    for p in _frozen:
        ta = float(p.get("transaction_amount") or 0)
        det = p.get("transaction_details") or {}
        net = float(det.get("net_received_amount") or 0)
        costo = (ta - net) if net else sum(float(f.get("amount") or 0)
                                           for f in (p.get("fee_details") or []))
        inst = int(p.get("installments") or 1)
        if inst <= 1:
            vol1 += ta; cost1 += costo; n1 += 1
        else:
            volc += ta; costc += costo; nc += 1
    try:
        while _run_live and token:
            r = requests.get("https://api.mercadopago.com/v1/payments/search",
                             headers={"Authorization": "Bearer " + token},
                             params={"sort": "date_approved", "criteria": "desc",
                                     "range": "date_approved", "begin_date": ini, "end_date": fin,
                                     "status": "approved", "offset": offset, "limit": 100}, timeout=30)
            if r.status_code >= 400:
                if not _frozen and offset == 0:
                    return None
                break
            data = r.json()
            res = data.get("results") or []
            for p in res:
                ta = float(p.get("transaction_amount") or 0)
                det = p.get("transaction_details") or {}
                net = float(det.get("net_received_amount") or 0)
                costo = (ta - net) if net else sum(float(f.get("amount") or 0)
                                                   for f in (p.get("fee_details") or []))
                inst = int(p.get("installments") or 1)
                if inst <= 1:
                    vol1 += ta; cost1 += costo; n1 += 1
                else:
                    volc += ta; costc += costo; nc += 1
            offset += 100
            if offset >= (data.get("paging") or {}).get("total", 0) or not res:
                break
    except Exception:
        if not _frozen:
            return None
    vol = vol1 + volc
    costo = cost1 + costc
    out = {"vol": round(vol, 2), "costo": round(costo, 2),
           "pct_total": round(costo / vol * 100, 2) if vol else 0.0,
           "pct_1pago": round(cost1 / vol1 * 100, 2) if vol1 else 0.0,
           "pct_cuotas": round(costc / volc * 100, 2) if volc else 0.0,
           "costo_1pago": round(cost1, 2), "costo_cuotas": round(costc, 2),
           "n_1pago": n1, "n_cuotas": nc}
    _MP_COST_CACHE[key] = (_t.time(), out)
    return out


