@app.post("/pf-facturacion-arca")
def pf_facturacion_arca():
    """Vincula ARCA: guarda CUIT + Punto de Venta + método (token de servicio o certificado)."""
    import re
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesión"})
    data = request.get_json(silent=True) or {}
    cuit = re.sub(r"\D", "", str(data.get("cuit") or ""))
    pv = re.sub(r"\D", "", str(data.get("pv") or "")) or "5"
    if len(cuit) != 11:
        return jsonify({"ok": False, "msg": "El CUIT debe tener 11 dígitos."})
    try:
        d = _json.loads(ARCA_CFG.read_text(encoding="utf-8"))
    except Exception:
        d = {}
    cuit_fmt = "%s-%s-%s" % (cuit[:2], cuit[2:10], cuit[10:])
    d[email] = {"cuit": cuit_fmt, "pv": pv,
                "nombre": (data.get("nombre") or "").strip(),
                "tipo": (data.get("tipo") or "Factura C · Monotributo").strip(),
                "metodo": (data.get("metodo") or "").strip(),
                "token": (data.get("token") or "").strip()}
    ARCA_CFG.parent.mkdir(parents=True, exist_ok=True)
    ARCA_CFG.write_text(_json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")
    return jsonify({"ok": True, "arca": {k: v for k, v in d[email].items() if k != "token"}})


@app.post("/pf-facturacion-informe")
def pf_facturacion_informe():
    """Exporta un .xlsx de las ventas FACTURADAS del período para el contador."""
    import openpyxl
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesión"}), 400
    data = request.get_json(silent=True) or {}
    desde = data.get("desde") or None
    hasta = data.get("hasta") or None
    rows = _facturacion_orders(email, desde, hasta) or []
    fact = [r for r in rows if r["facturada"]]
    if not fact:
        return jsonify({"ok": False, "msg": "No hay ventas marcadas como facturadas en ese período."}), 400
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "Facturación"
    ws.append(["Fecha emisión", "Fecha venta", "Pedido", "Cliente", "CUIT/DNI", "Medio",
               "Localidad", "Provincia", "CP", "Dirección", "Email", "Comprobante", "Total"])
    for r in sorted(fact, key=lambda x: int(x["num"]) if str(x["num"]).isdigit() else 0):
        ws.append([r.get("emit", "") or (r.get("fecha") or "")[:10], r.get("fecha_dmy", "") or (r.get("fecha") or "")[:10],
                   r["num"], r["nombre"], r.get("dni", ""), r.get("medio", ""),
                   r.get("localidad", ""), r.get("provincia", ""), r.get("cp", ""),
                   r.get("dir_fiscal", ""), r.get("email", ""), r.get("comprobante", ""),
                   r["total"]])
    out = DATA_DIR / ("Informe-Facturacion-%s.xlsx" % _dt.datetime.now().strftime("%Y%m%d-%H%M%S"))
    wb.save(str(out))
    return send_file(str(out), as_attachment=True, download_name=out.name)


@app.post("/pf-despachos-marcar")
def pf_despachos_marcar():
    email = _user_actual()
    if not email:
        return jsonify({"ok": False})
    data = request.get_json(silent=True) or {}
    nums = [str(n) for n in (data.get("nums") or [])]
    accion = (data.get("accion") or "exportada").strip()   # exportada / enviada / empaquetar
    st = _desp_state(email)
    for n in nums:
        if accion == "empaquetar":
            st.pop(n, None)
        else:
            st[n] = accion
    _desp_save(email, st)
    return jsonify({"ok": True, "n": len(nums), "accion": accion})


ANDREANI_TPL = RAIZ / "EnvioMasivoExcelPaquetes.xlsx"


def _split_nombre(nm):
    # el cliente a veces mete el MAIL en el nombre ('juan@gmail.com Delfino Juan Carlos') → lo sacamos
    p = [t for t in (nm or "").strip().split() if "@" not in t]
    if not p:
        p = (nm or "").strip().split()
    if not p:
        return "Cliente", "Cliente"      # sin nombre → placeholder (Andreani exige Nombre Y Apellido)
    if len(p) == 1:
        return p[0], p[0]                # UNA sola palabra → va en Nombre Y Apellido; si no, Andreani
        #                                  rechaza "El campo Apellido es obligatorio" (fila del pedido)
    return " ".join(p[:-1]), p[-1]


def _calle_num(dir_):
    import re
    d = (dir_ or "").strip()
    nums = [(m.start(), m.group()) for m in re.finditer(r"\d+", d)]
    if not nums:
        return d, ""
    # la altura suele ser el número MÁS LARGO ('Las virjenes 1743 ... casa4' → 1743, no el 4;
    # 'Calle 44 665' → 665). Desempate por longitud → el primero.
    pos, val = max(nums, key=lambda x: (len(x[1]), -x[0]))
    calle = (d[:pos].strip().rstrip(", ") or d.replace(val, "", 1).strip() or d)
    return calle, val


_AND_GRAVE = {"à": "á", "è": "é", "ì": "í", "ò": "ó", "ù": "ú", "À": "Á", "È": "É", "Ì": "Í",
              "Ò": "Ó", "Ù": "Ú", "â": "a", "ê": "e", "î": "i", "ô": "o", "û": "u",
              "ä": "a", "ë": "e", "ï": "i", "ö": "o", "ã": "a", "õ": "o", "ç": "c", "Ç": "C"}
_AND_OK = set("0123456789 .")


def _and_txt(s):
    """Limpia un campo de TEXTO para Andreani (Calle, Piso, Depto, Nombre, Apellido, Observaciones).
    Andreani rechaza símbolos como '/' y '-'. Dejamos letras (con acentos ESPAÑOLES), números,
    espacio y punto; normalizamos acentos raros (ù→ú); el resto (/, -, #, |, etc.) → espacio.
    NO inventa: solo saca lo que Andreani no acepta. No cambia el sentido del dato."""
    s = "".join(_AND_GRAVE.get(ch, ch) for ch in str(s or ""))
    out = []
    for ch in s:
        if ch.isalpha() and (ch.isascii() or ch in "áéíóúñüÁÉÍÓÚÑÜ"):
            out.append(ch)
        elif ch in _AND_OK:
            out.append(ch)
        else:
            out.append(" ")
    return _re_and.sub(r"\s+", " ", "".join(out)).strip(" .")


def _and_num_limpio(s):
    """Número de calle para Andreani: SOLO dígitos (rechaza 'S/N', '-', letras). Sin dígitos → ''. """
    return _re_and.sub(r"\D", "", str(s or ""))


def _and_calle_limpia(s):   # compat: alias del limpiador de texto
    return _and_txt(s)


# ===== Resolvedor Andreani: sucursal exacta + Prov/Loc/CP oficial (sin login, endpoints públicos) =====
import re as _re_and
import re   # 're' suelto lo usan varias funciones (seg/shopify) → disponible a nivel módulo
import unicodedata as _ud_and

_AND_CFG = {"cpidx": None, "sucs": None}


def _and_norm(s):
    s = _ud_and.normalize("NFKD", str(s or "")).encode("ascii", "ignore").decode()
    return _re_and.sub(r"[^A-Z0-9 ]", " ", s.upper())


def _and_normP(s):
    s = _ud_and.normalize("NFKD", str(s or "")).encode("ascii", "ignore").decode()
    return _re_and.sub(r"\s+", " ", s.strip().upper())


def _and_toks(s):
    return [w for w in _and_norm(s).split() if w]


def _and_cp4(x):
    m = _re_and.search(r"(\d{4})", str(x or ""))
    return m.group(1) if m else ""


def _and_split_tel(p):
    d = _re_and.sub(r"\D", "", str(p or ""))
    d = _re_and.sub(r"^0", "", d)
    d = _re_and.sub(r"^549?", "", d)
    if d.startswith("11"):
        return "11", d[2:]
    return d[:3], d[3:]


def _and_cfg(wb):
    if _AND_CFG["cpidx"] is None:
        cpidx, sucs = {}, []
        try:
            for row in wb["Configuracion"].iter_rows(min_row=2, values_only=True):
                if row and row[0]:
                    sucs.append(str(row[0]).strip())
                if row and len(row) > 4 and row[4]:
                    v = str(row[4]).strip()
                    cpidx.setdefault(_re_and.sub(r"\D", "", v.split("/")[-1]), []).append(v)
        except Exception:
            pass
        _AND_CFG["cpidx"], _AND_CFG["sucs"] = cpidx, sucs
        _AND_CFG["norm"] = {_and_norm(o): o for o in sucs}   # índice para match EXACTO
    return _AND_CFG["cpidx"], _AND_CFG["sucs"]


def _and_suc_exacto(zeny):
    """Match EXACTO al nombre OFICIAL de Andreani. El método del cliente YA trae el nombre tal cual
    Andreani lo nombra; si coincide exacto es 100% seguro (no adivina)."""
    idx = _AND_CFG.get("norm") or {}
    s = _re_and.sub(r"^.*?[-–—]\s*", "", str(zeny)).strip()
    if "HOP" in str(zeny).upper():
        addr = _re_and.sub(r"\s*\(.*?\)\s*$", "", s)          # saca el nombre de la tienda (paréntesis)
        key = _and_norm(addr)
        if not key.startswith("PUNTO ANDREANI HOP"):          # formato viejo trae solo la dirección
            key = _and_norm("PUNTO ANDREANI HOP " + addr)     # formato nuevo ya trae 'PUNTO ANDREANI HOP ...'
        return idx.get(key)
    return idx.get(_and_norm(s))                              # 'Ciudad (Detalle)'


def _and_pcl(cp, prov, cpidx):
    cands = cpidx.get(_and_cp4(cp), [])
    if not cands:
        return None
    pn = _and_normP(prov)
    mism = [c for c in cands if pn and (pn in _and_normP(c) or _and_normP(c.split("/")[0]) in pn)]
    pool = sorted(mism or cands, key=lambda c: len(c.split("/")[1]) if len(c.split("/")) > 2 else 99)
    return pool[0]


def _and_mid(zeny):
    m = _re_and.search(r"[-–—]\s*(.*?)\s*\((.*)\)\s*$", str(zeny))
    return (m.group(1) if m else _re_and.sub(r".*?[-–—]\s*", "", str(zeny))).strip()


def _and_partes(s):
    """Ciudad (antes del paréntesis) y detalle (dentro del paréntesis) del método del cliente.
    Ej 'ANDREANI SUCURSAL - San Martin (Mendoza)' → ({SAN,MARTIN}, {MENDOZA})."""
    m = _re_and.search(r"[-–—]\s*(.*?)\s*(?:\((.*)\))?\s*$", str(s))
    if m:
        return set(_and_toks(m.group(1))), set(_and_toks(m.group(2) or ""))
    return set(_and_toks(s)), set()


def _and_partes_of(o):
    """Ciudad y detalle de una sucursal OFICIAL de la plantilla ('CIUDAD (CALLE/PROV)')."""
    m = _re_and.search(r"^(.*?)\s*\((.*)\)\s*$", str(o))
    if m:
        return set(_and_toks(m.group(1))), set(_and_toks(m.group(2)))
    return set(_and_toks(o)), set()


def _and_suc_excel(zeny, sucs):
    """Mapea la sucursal/HOP que eligió el cliente al nombre OFICIAL de Andreani.
    Incluye el paréntesis (provincia/detalle) en la búsqueda y le da peso fuerte a que la
    CIUDAD del cliente coincida con la ciudad oficial → así jamás cruza de ciudad/provincia
    (evita el caso 'San Martín (Mendoza)' → 'Corrientes (San Martín)')."""
    es_hop = "HOP" in str(zeny).upper()
    ccity, cdet = _and_partes(zeny)
    q = ccity | cdet
    qn = {w for w in q if w.isdigit()}
    qw = {w for w in q if not w.isdigit() and len(w) >= 4}
    ccity_w = {w for w in ccity if not w.isdigit()}
    best, bs, bnum, bword = None, -1, False, False
    for o in sucs:
        if es_hop != _and_norm(o).startswith("PUNTO ANDREANI HOP"):
            continue
        ocity, odet = _and_partes_of(o)
        ts = ocity | odet
        nums = {w for w in ts if w.isdigit()}
        sc = sum(len(w) for w in (q & ts))
        numok = bool(qn and nums and qn & nums)
        if numok:
            sc += 25
        if ccity_w and ccity_w <= ocity:      # la ciudad del cliente coincide con la ciudad oficial
            sc += 30
        if sc > bs:
            bs, best, bnum, bword = sc, o, numok, bool(qw & {w for w in ts if len(w) >= 4})
    conf = (bnum and bword) if es_hop else (bs >= 4)
    return best, conf


def _and_suc_live(zeny, cp):
    """HOP exacto con los endpoints PÚBLICOS de Andreani (autosuggest + byCoordenadas). Sin login."""
    hd = {"User-Agent": "Mozilla/5.0", "Referer": "https://www.andreani.com/buscar-sucursal"}
    es_hop = "HOP" in str(zeny).upper()
    addr = _and_mid(zeny)
    qn = {w for w in _and_toks(addr) if w.isdigit()}
    qw = {w for w in _and_toks(addr) if not w.isdigit() and len(w) >= 4}
    if not qn:
        return None
    for q in [f"{addr}, {cp}", addr]:
        try:
            js = requests.get("https://www.andreani.com/api/autosuggest",
                              params={"q": q, "limit": 6}, headers=hd, timeout=12).json()
        except Exception:
            continue
        for it in (js.get("items") or []):
            pos = it.get("position") or {}
            if not pos:
                continue
            try:
                pts = requests.get("https://www.andreani.com/api/sucursales/byCoordenadas",
                                   params={"lat": pos["lat"], "lng": pos["lng"]}, headers=hd, timeout=12).json()
            except Exception:
                continue
            for p in (pts if isinstance(pts, list) else []):
                nom = p.get("descripcion", "")
                if es_hop and "hop" not in nom.lower():
                    continue
                nt = set(_and_toks(nom))
                if (qn & {w for w in nt if w.isdigit()}) and (qw & {w for w in nt if len(w) >= 4}):
                    return nom
    return None


def _and_suc_coord(lat, lng, es_hop, punto_id="", sucs=None):
    """Sucursal EXACTA por las COORDENADAS del punto que eligió el cliente (TiendaNube las trae en
    shipping_pickup_details.address). byCoordenadas de Andreani devuelve los puntos por cercanía:
    el de distancia≈0 (o el que matchea el id del punto = shipping_option_reference) ES el punto
    elegido, y su 'descripcion' es el nombre OFICIAL tal cual el dropdown de la plantilla.
    Determinístico: si no mapea a una sucursal REAL de la lista → None (no inventa, no cruza de lado)."""
    try:
        lat = float(lat); lng = float(lng)
    except Exception:
        return None
    if not lat or not lng:
        return None
    hd = {"User-Agent": "Mozilla/5.0", "Referer": "https://www.andreani.com/buscar-sucursal"}
    try:
        pts = requests.get("https://www.andreani.com/api/sucursales/byCoordenadas",
                           params={"lat": lat, "lng": lng}, headers=hd, timeout=12).json()
    except Exception:
        return None
    if not isinstance(pts, list) or not pts:
        return None
    # id del punto que eligió el cliente (último número del shipping_option_reference, ej ...:pickup:17910)
    m = _re_and.search(r"(\d+)\s*$", str(punto_id or ""))
    pid = m.group(1) if m else ""
    # 1) match EXACTO por id del punto elegido → es DEFINITIVO. Si su nombre no está en el dropdown
    #    de la plantilla → None (a REVISAR): no lo cambio por otro punto cercano.
    if pid:
        for p in pts:
            if str(p.get("puntoDeTerceroId") or "") == pid:
                return _and_suc_exacto(p.get("descripcion") or "")   # puede ser None → REVISAR

    def _dist(p):
        try:
            return float(p.get("distancia"))
        except Exception:
            return 9e9
    # 2) sin id (o el id ya no está en Andreani): SOLO acepto el punto que está EXACTAMENTE en esas
    #    coordenadas (dist ≈ 0). Si el más cercano no está prácticamente encima (>80 m), NO es el que
    #    eligió el cliente → None (REVISAR). NUNCA agarro "el de al lado" (ese fue el bug del 9 de julio).
    nearest = min(pts, key=_dist)
    if _dist(nearest) <= 80:
        nom = nearest.get("descripcion") or ""
        if (not es_hop) or ("hop" in nom.lower()):
            return _and_suc_exacto(nom)   # puede ser None → REVISAR
    return None


def _hop_passthrough(zeny):
    """El nombre del punto que da Envialo/TiendaNube (shipping_pickup_details.name) ES el punto
    oficial que eligió el cliente. Si es un HOP claro de Andreani (PUNTO ANDREANI HOP + dirección
    con número), lo devolvemos normalizado para el Excel AUNQUE no esté en nuestra plantilla:
    Andreani lo acepta igual — Envialo escribe estos nombres tal cual y funcionan (verificado con
    'PUNTO ANDREANI HOP SAN MARTIN 1927', que no está en ningún desplegable y despacha bien).
    Formato = MAYÚSCULAS sin acentos, como los escribe Envialo. Sino → None."""
    z = str(zeny or "")
    i = z.upper().find("PUNTO ANDREANI HOP")
    if i >= 0:
        z = z[i:]
    else:
        j = z.upper().find("HOP ")
        if j < 0:
            return None
        z = "PUNTO ANDREANI " + z[j:]
    z = _re_and.sub(r"\s*\(.*?\)\s*$", "", z)     # saca '(nombre de la tienda)' al final
    z = _re_and.sub(r"\s*[-–—]\s*", " ", z)        # 'HOP - Av X' → 'HOP Av X'
    out = _and_normP(z)                            # MAYÚSCULAS, sin acentos, espacios simples
    if not out.startswith("PUNTO ANDREANI HOP") or not _re_and.search(r"\d", out):
        return None
    return out


_SUC_GENERICO = ("ANDREANI SUCURSAL", "PUNTO DE RETIRO", "ANDREANI PUNTO DE RETIRO",
                 "SUCURSAL", "RETIRO EN SUCURSAL", "CORREO ARGENTINO", "OCA", "ANDREANI")


def _punto_passthrough(zeny):
    """El punto que da Envialo (HOP de terceros O sucursal propia de Andreani) es la fuente de
    verdad: lo usamos tal cual aunque no esté en nuestra plantilla (Andreani lo acepta). Cubre:
      - HOP:       'PUNTO ANDREANI HOP <calle> <nº>'
      - Sucursal:  'CIUDAD (DETALLE)'  (ej 'CANNING (AV CASTEX)')
    Rechaza etiquetas GENÉRICAS sin punto específico (esas van a coord/vivo/REVISAR)."""
    hp = _hop_passthrough(zeny)
    if hp:
        return hp
    s = _re_and.sub(r"^.*?[-–—]\s*", "", str(zeny or "")).strip()   # saca 'Andreani Sucursal —'
    if _re_and.match(r"^[^()]+\([^()]+\)\s*$", s):                  # formato 'CIUDAD (DETALLE)'
        out = _and_normP(s)
        base = _and_normP(_re_and.sub(r"\s*\(.*\)\s*$", "", s))     # la parte antes del paréntesis
        if len(out) >= 5 and base and base not in _SUC_GENERICO and "PUNTO DE RETIRO" not in out:
            return out
    return None


_AND_DOM_PH = ("casa", "domicilio", "particular", "depto", "departamento", "dpto", "s/n", "sn",
               "sin numero", "sin número", "local", "plata baja", "planta baja", "pb")


def _and_letters(s):
    return _re_and.sub(r"[^A-Za-zÁÉÍÓÚÑáéíóúñ]", "", str(s or ""))


def _and_domicilio(calle, numero, extra):
    """Devuelve (calle, numero, depto) para la fila de domicilio. Recupera el número (y la calle real)
    del Apartamento (address2) cuando el cliente lo cargó ahí — caso muy común. NO inventa: si no hay
    altura en ningún lado, numero queda '' (el generador lo pone en '0' y lo marca para revisar)."""
    calle = str(calle or "").strip()
    numero = str(numero or "").strip()
    extra = str(extra or "").strip()
    if not _re_and.search(r"\d", numero):   # 'SN', 'S/N', 'sin número' → vacío, así recupera la altura real
        numero = ""
    calle_ph = calle.lower() in _AND_DOM_PH
    # "Calle 60" / "Calle 39" / "17 n" sola = nombre de calle numerada (NO es la altura) → altura del apto
    _num_sola = bool(_re_and.match(r"^\d{1,4}\s*(n|n°|nº|bis)?\s*$",
                                   _re_and.sub(r"^\s*(calle|av\.?|avenida)\s+", "", calle, flags=_re_and.I).strip(),
                                   _re_and.I))
    if not numero and not _num_sola:                 # 1) número pegado en la calle ("Grecia 1036")
        c2, n2 = _calle_num(calle)
        if n2:
            calle, numero = c2, n2
    # calle "débil" = placeholder ("Casa"), basura sin nombre NI número ("A"), o un número suelto de
    # 4+ dígitos (tipo CP, ej "8322", NO una calle). Calle numerada corta ("86 n", "70") es válida.
    calle_debil = (calle_ph
                   or (not _re_and.search(r"[A-Za-zÁÉÍÓÚÑáéíóúñ]{3,}", calle)
                       and not _re_and.search(r"\d", calle))
                   or bool(_re_and.fullmatch(r"\d{4,}", calle.strip())))
    if not numero and extra:                         # 2) el número (y a veces la calle) está en el Apartamento
        mx = _re_and.search(r"\d{1,6}", extra)
        if mx:
            numero = mx.group(0)
            apt_calle = _re_and.sub(r"^(calle|av\.?|avenida)\s+", "", extra[:mx.start()].strip(" ,.-"), flags=_re_and.I).strip()
            if calle_debil and len(_and_letters(apt_calle)) >= 3:   # la calle real estaba en el apartamento
                calle = apt_calle
            extra = extra[mx.end():].strip(" ,.-")
    if calle_debil and len(_and_letters(calle)) < 3 and len(_and_letters(extra)) >= 3:
        calle = extra; extra = ""                    # 3) calle débil y el apto trae la calle (sin número)
    return _and_txt(calle), _and_num_limpio(numero), _and_txt(extra)


@app.post("/pf-despachos-excel")
def pf_despachos_excel():
    """Genera el Excel de carga masiva de Andreani (2 hojas: A domicilio / A sucursal)
    con los pedidos seleccionados, mapeando los campos de Shopify a la plantilla.
    Resuelve la sucursal al nombre OFICIAL de Andreani y arregla DNI/teléfono/Prov-Loc-CP."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False}), 401
    data = request.get_json(silent=True) or {}
    nums = set(str(n) for n in (data.get("nums") or []))
    tienda = (data.get("tienda") or "todas").strip()   # filtro por tienda: no mezclar Shopify/TN (mismos nºs)
    if not nums:
        return jsonify({"ok": False, "msg": "sin pedidos"}), 400
    rows = _despachos_orders(email) or []
    sel = [r for r in rows if str(r["num"]) in nums and (tienda == "todas" or r.get("tienda") == tienda)]
    if not sel:
        return jsonify({"ok": False, "msg": "no encontré esos pedidos"}), 404
    tpl = ANDREANI_TPL if ANDREANI_TPL.exists() else Path(_os.path.expanduser("~/Downloads/EnvioMasivoExcelPaquetes.xlsx"))
    if not tpl.exists():
        return jsonify({"ok": False, "msg": "falta la plantilla EnvioMasivoExcelPaquetes.xlsx en el servidor"}), 500
    try:
        import openpyxl
    except Exception:
        return jsonify({"ok": False, "msg": "falta openpyxl en el servidor"}), 500
    try:
        wb = openpyxl.load_workbook(tpl)
        ws_dom = wb["A domicilio"]
        ws_suc = wb["A sucursal"]
    except Exception as e:
        return jsonify({"ok": False, "msg": "no pude abrir la plantilla: %s" % e}), 500
    # Mínimos Andreani (jul-2026): SUMA de lados (alto+ancho+prof) >= 35 cm y peso >= 1 kg.
    # 15+12+10 = 37 cm (cumple con margen). Peso FIJO 1000 g (1 kg) para TODOS los paquetes:
    # no escala con las unidades a propósito (si escalara, Andreani cobra más por peso declarado).
    ALTO, ANCHO, PROF = 15, 12, 10
    PESO = 1000
    cpidx, sucs = _and_cfg(wb)   # lista oficial de la propia plantilla (sucursales + Prov/Loc/CP)
    envialo_ov = _envialo_suc(_user_actual())   # si subiste el Excel de Envialo, esas sucursales MANDAN (1=1)
    envialo_excl = _envialo_excl(_user_actual())  # las que NO coincidían con Envialo → se despachan por Envialo, NO van acá
    r_dom = r_suc = 3
    faltantes = []               # domicilios sin número de calle → NO inventamos, avisamos
    revisar = []                 # sucursales que no pudimos mapear con confianza → NO inventamos
    por_envialo = []             # pedidos que van por Envialo (no coincidían) → los saco del Excel de Andreani
    for r in sel:
        if str(r["num"]) in envialo_excl:   # no coincidía con Envialo → se despacha por Envialo, no lo meto acá
            por_envialo.append(str(r["num"]))
            continue
        nom, ape = _split_nombre(r["nombre"])
        nom, ape = _and_txt(nom), _and_txt(ape)               # Andreani rechaza símbolos en nombre/apellido
        valor = max(int(round(r.get("total") or 0)), 30000)   # piso: Andreani rechaza valor declarado 0/muy bajo
        peso = PESO
        dni = str(r.get("dni") or "").strip() or "00000000"   # Andreani exige DNI
        tel_cod, tel_num = _and_split_tel(r.get("tel"))        # teléfono partido en código/número
        email = r.get("email") or ""
        if r["tipo"] == "sucursal":
            # Sucursal: la manda Envialo (1=1) o el resolvedor (exacto→coord→vivo). PERO la carga masiva
            # de Andreani SOLO acepta valores del desplegable → validamos: si el punto NO está en el
            # desplegable (ej San Martín 1927), va a REVISAR (se despacha por Envialo), NO rompe el Excel.
            suc_raw = r.get("suc_nombre") or ""
            of = envialo_ov.get(str(r["num"]))          # 1=1: si Envialo la mandó, gana Envialo
            if not of:
                of, _via = _resolver_suc_completo(suc_raw, r.get("suc_lat"), r.get("suc_lng"),
                                                  r.get("suc_pid"), r.get("cp"), sucs)
            of = _and_suc_exacto(of) if of else None    # SOLO vale si está en el desplegable de Andreani
            if not of:
                # No entra en el desplegable de Andreani. Si está en el Excel de Envialo, la despachás por
                # Envialo → la excluyo del Excel (no freno). Si NO está en Envialo, sí aviso (revisar).
                if str(r["num"]) in envialo_ov:
                    por_envialo.append(str(r["num"]))
                else:
                    revisar.append(str(r["num"]))
                continue
            vals = [None, peso, ALTO, ANCHO, PROF, valor, r["num"], nom, ape, dni,
                    email, tel_cod, tel_num, of]
            for c, v in enumerate(vals, start=1):
                ws_suc.cell(r_suc, c, v)
            r_suc += 1
        else:
            # Calle/Número REALES de la orden (TN los trae aparte; Shopify mete calle+número en address1).
            # Calle/Número REALES: recupera el número (y la calle) del Apartamento si el cliente lo puso ahí.
            calle, numero, depto = _and_domicilio(r.get("calle"), r.get("numero"), r.get("extra"))
            if not numero:                                 # sin numeración real en ningún lado → 0 (NO inventa)
                numero = "0"; faltantes.append(str(r["num"]))
            pcl = _and_pcl(r.get("cp"), r.get("provincia"), cpidx) or _and_normP(r.get("provincia"))
            vals = [None, peso, ALTO, ANCHO, PROF, valor, r["num"], nom, ape, dni,
                    email, tel_cod, tel_num, calle, numero, "", depto, pcl, ""]
            for c, v in enumerate(vals, start=1):
                ws_dom.cell(r_dom, c, v)
            r_dom += 1
    # Los domicilios sin número van con "0" (Andreani exige numérico) → NO bloquean el Excel.
    # Solo frenamos si una SUCURSAL no se pudo mapear al nombre oficial (mandaría a otra sucursal).
    if revisar:
        wb.close()
        return jsonify({"ok": False, "msg": "No pude resolver la SUCURSAL oficial de Andreani de: "
                        + ", ".join("#" + n for n in revisar) + " (no la invento para no mandarla a otra "
                        "sucursal). Revisá esos pedidos o destildalos y generá el Excel con el resto."}), 400
    import io
    buf = io.BytesIO()
    wb.save(buf)
    wb.close()
    buf.seek(0)
    return send_file(buf, as_attachment=True, download_name="Andreani.xlsx",
                     mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")


@app.post("/pf-despachos-sku-sync")
def pf_despachos_sku_sync():
    """Trae los SKU de los productos de la tienda a la sección Productos."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False})
    n = 0
    try:
        tk = _shop_tokens().get(email)
        if tk and tk.get("access_token"):
            r = requests.get("https://%s/admin/api/2026-07/products.json" % tk.get("shop"),
                             headers={"X-Shopify-Access-Token": tk.get("access_token")},
                             params={"limit": 250, "fields": "id,variants"}, timeout=30)
            skus = _skus_map(email)
            for p in ((r.json() or {}).get("products") or []):
                for v in (p.get("variants") or []):
                    sk = (v.get("sku") or "").strip()
                    if sk:
                        skus[str(p.get("id"))] = sk
                        n += 1
                        break
            _skus_save(email, skus)
    except Exception:
        pass
    return jsonify({"ok": True, "n": n})


_SKU_JOBS = {}      # {job_id: {done,total,msg,listo,error,pdf,email,stats}} — progreso del estampado


def _sku_de_items(items, skus):
    """SKU a estampar = qué empaquetar, según la config de Productos del usuario (tipo
    spray/fijo/xN por CADA producto). NO hardcodea VisionPure: usa lo que el usuario cargó.
    items: [(sku_key, cantidad, nombre_producto)]."""
    # Los UNITARIOS con la misma base se SUMAN (2 renglones de 'x1 Pote' → 'x2 Pote', no 'x1 + x1').
    # Los variable/fijo se dejan tal cual (el 'spray' usa su propio ' + ', ej '3 60ML + 1 30ML').
    uni = {}          # base_norm -> [base_display, total_qty]  (mantiene orden con uni_ord)
    uni_ord = []
    otras = []
    for key, qty, pname in items:
        if not qty or qty <= 0:
            continue
        cfg = skus.get(str(key))
        if cfg is None:
            cfg = {"tipo": "xn", "base": (pname or "").strip()}   # sin configurar → 'xN nombre'
        c = _sku_cfg(cfg)
        if c["tipo"] == "unitario":
            base = (c["base"] or "").strip()
            k = base.lower()
            if k not in uni:
                uni[k] = [base, 0]; uni_ord.append(k)
            uni[k][1] += int(qty)
        else:
            s = _sku_calc(cfg, qty)
            if s:
                otras.append(s)
    partes = []
    for k in uni_ord:
        base, tot = uni[k]
        partes.append((("x%d %s" % (tot, base)).strip()) if base else ("x%d" % tot))
    partes += otras
    return " + ".join(partes)


def _sku_nint(texto):
    m = _re_and.search(r'N[°ºo]?\s*Interno\s*:\s*#?\s*(\d+)', texto)
    return m.group(1) if m else ""


def _sku_id(texto):
    m = _re_and.search(r'(?:N[°ºo]?\s*Interno|Id)\s*:\s*#?\s*(\d+)', texto, _re_and.I)
    return m.group(1) if m else ""


def _sku_pedido(texto, nuevo):
    return _sku_nint(texto) if nuevo else _sku_id(texto)


def _sku_estampar_nuevo(pg, sku):
    """Andreani ORIGINAL (carga masiva): SKU a la izquierda del 'Bulto 1 / 1', caja negra, texto blanco."""
    import fitz
    anc = pg.search_for("1 / 1") or pg.search_for("Bulto")
    if anc:
        r = anc[0]; xr = r.x0 - 6.0; y = r.y1 - 3.0
    else:
        xr, y = 157.0, 107.0
    fs = 9.5
    w = fitz.get_text_length(sku, fontname="hebo", fontsize=fs)
    x0 = xr - w; cap = fs * 0.70; pad_x, pad_y = 3.0, 2.0
    caja = fitz.Rect(x0 - pad_x, y - cap - pad_y, xr + pad_x, y + pad_y)
    pg.draw_rect(caja, fill=(0, 0, 0), color=(0, 0, 0), width=0)
    pg.insert_text(fitz.Point(x0, y), sku, fontsize=fs, fontname="hebo", color=(1, 1, 1))


def _sku_estampar_ecom(pg, sku, texto):
    """Formato 'ENCOMIENDA ECOMMERCE': caja negra en el hueco según domicilio/sucursal."""
    import fitz
    anc = (pg.search_for("ID: #") or pg.search_for("Id: #") or pg.search_for("ID:") or pg.search_for("Id:"))
    r = anc[0] if anc else None
    es_suc = bool(r and r.y0 < 90)
    fs = 11.0
    w = fitz.get_text_length(sku, fontname="hebo", fontsize=fs)
    if es_suc:
        x0 = 8.0; y = (r.y1 + 30.0) if r else 113.0
    else:
        x0 = 95.0; y = (r.y0 - 4.0) if r else 98.0
    pad_x, pad_y, cap = 4.0, 3.0, fs * 0.72
    caja = fitz.Rect(x0 - pad_x, y - cap - pad_y, x0 + w + pad_x, y + pad_y)
    pg.draw_rect(caja, fill=(0, 0, 0), color=(0, 0, 0), width=0)
    pg.insert_text(fitz.Point(x0, y), sku, fontsize=fs, fontname="hebo", color=(1, 1, 1))


def _sku_estampar_std(pg, sku):
    """Etiqueta estándar (284×425): recuadro amarillo con el SKU, anclado al 'Id:', lado izquierdo."""
    import fitz
    id_rects = pg.search_for("Id:")
    if id_rects:
        r = id_rects[0]; y1 = r.y0 - 1.5; x0, x1 = 4.0, 186.0
    else:
        x0, x1, y1 = 4.0, 186.0, 100.0
    y0 = y1 - 16.5
    pg.draw_rect(fitz.Rect(x0, y0, x1, y1), color=(0.85, 0.45, 0), fill=(1, 0.9, 0.45), width=1.2)
    pg.insert_text(fitz.Point(x0 + 6, y1 - 4.5), "SKU:  " + sku, fontsize=9, fontname="hebo", color=(0.55, 0.05, 0.05))


def _sku_norm(s):
    """Normaliza para comparar nombres: sin acentos, mayúsculas, solo letras/números."""
    s = _ud_and.normalize("NFKD", str(s or "")).encode("ascii", "ignore").decode()
    s = _re_and.sub(r"[^A-Za-z0-9 ]", " ", s).upper()
    return _re_and.sub(r"\s+", " ", s).strip()


def _sku_tokens(nombre):
    """Tokens 'fuertes' de un nombre (>=3 letras) para comparar destinatario ↔ pedido."""
    return {t for t in _sku_norm(nombre).split() if len(t) >= 3 and not t.isdigit()}


def _sku_nombre_coincide(label_nom, pedido_nom):
    """True si el destinatario de la etiqueta y el del pedido comparten nombre/apellido.
    Si en alguno falta el dato, no bloquea (True)."""
    a, b = _sku_tokens(label_nom), _sku_tokens(pedido_nom)
    if not a or not b:
        return True
    return bool(a & b)


def _sku_label_nombre(texto):
    """Nombre del destinatario que figura en la etiqueta (para verificar el match)."""
    m = _re_and.search(r"Destinatario\s*:\s*(.+)", texto, _re_and.I)
    return m.group(1).strip() if m else ""


def _sku_pedidos_map(email):
    """{nº pedido → [ {'nom','items','tienda'}, ... ] } (lista: el mismo nº puede estar en las 2 tiendas) de las
    tiendas conectadas (Shopify + Tiendanube). Trae los PRODUCTOS de cada pedido para calcular
    el SKU con la config de Productos. Guarda el nombre para verificar el match. RÁPIDO (cacheado)."""
    import time as _t
    _sku_ped_load()                        # trae la caché de disco (tras deploy) → 1er sync NO arranca en frío
    _c = _SKU_PED_CACHE.get(email)
    if _c and (_t.time() - _c[0] < _SKU_PED_TTL):
        return _c[1]                       # caché fresco → no rebaja Shopify/TN de nuevo
    deadline = _t.time() + 22              # TOPE DURO: el sync NUNCA tarda más de ~22s (antes se colgaba hasta 40min
    #                                        si Shopify tiraba 429 y reintentaba 80 veces × 30s)
    mapa = {}
    # --- Tiendanube (sku_key = 'tn:<product_id>', igual que en Productos) ---
    tk = _tn_tokens().get(email)
    if tk and tk.get("access_token") and tk.get("store_id"):
        store, hdr = tk["store_id"], _tn_headers(tk["access_token"])
        for page in (1, 2):
            if _t.time() > deadline:
                break
            try:
                r = requests.get("%s/%s/orders" % (TN_API, store), headers=hdr, params={
                    "per_page": 200, "page": page, "sort": "-id", "payment_status": "paid",
                    "fields": "number,products,contact_name,shipping_address"}, timeout=12)
                d = r.json() if r.content else []
            except Exception:
                d = []
            if not isinstance(d, list) or not d:
                break
            for o in d:
                items = []
                for p in (o.get("products") or []):
                    nm = p.get("name")
                    if isinstance(nm, dict):
                        nm = nm.get("es") or next(iter(nm.values()), "") if nm else ""
                    items.append(("tn:%s" % p.get("product_id"), int(p.get("quantity") or 0), nm or ""))
                nom = ((_D(o.get("shipping_address"))).get("name") or o.get("contact_name") or "")
                mapa.setdefault(str(o.get("number")), []).append({"nom": nom, "items": items, "tienda": "tn"})
            if len(d) < 200:
                break
    # --- Shopify (sku_key = '<product_id>') ---
    tks = _shop_tokens().get(email)
    if tks and tks.get("access_token") and _t.time() < deadline:
        hasta = _hoy()
        desde = (_dt.date.today() - _dt.timedelta(days=35)).isoformat()   # 60→35 días: las etiquetas son de pedidos recientes
        _got = _SHOP_SEM.acquire(timeout=4)     # tope de ops pesadas → no cuelga los hilos del server
        if _got:
            try:
                for o in _shopify_orders(tks.get("shop"), tks.get("access_token"), desde, hasta,
                                         deadline=deadline, max_pages=10, timeout=12):
                    num = str(o.get("order_number") or o.get("name") or "").replace("#", "").strip()
                    if not num:
                        continue
                    items = []
                    for li in (o.get("line_items") or []):
                        items.append((str(li.get("product_id") or ""), int(li.get("quantity") or 0),
                                      li.get("title") or li.get("name") or ""))
                    sa = _D(o.get("shipping_address"))
                    cu = o.get("customer") or {}
                    nom = (sa.get("name") or ((cu.get("first_name", "") + " " + cu.get("last_name", "")).strip()))
                    mapa.setdefault(num, []).append({"nom": nom, "items": items, "tienda": "shopify"})
            except Exception:
                pass
            finally:
                _SHOP_SEM.release()
    _SKU_PED_CACHE[email] = (_t.time(), mapa)
    _sku_ped_save()                        # persisto a disco → el próximo deploy no arranca frío
    return mapa


def _sku_hoja_empaquetar(doc, detalle):
    """Hoja final A4 'PARA EMPAQUETAR': cuántas bolsas de cada SKU (genérico, sin hardcodear
    ningún producto). Cuenta cuántas etiquetas comparten el mismo SKU."""
    import fitz
    from collections import Counter
    paquetes = Counter(d["sku"] for d in detalle if d.get("sku"))
    if not paquetes:
        return
    NEG, BLA = (0, 0, 0), (1, 1, 1)
    pg = doc.new_page(width=595, height=842)
    pg.insert_text((50, 92), "PARA EMPAQUETAR", fontname="hebo", fontsize=30, color=NEG)
    pg.draw_line((50, 112), (545, 112), color=NEG, width=1.2)
    y = 175
    total_bolsas = 0
    for k, v in sorted(paquetes.items(), key=lambda x: (-x[1], x[0])):
        total_bolsas += v
        etq = "%dX %s" % (v, "BOLSA" if v == 1 else "BOLSAS")
        fs = 20
        w = fitz.get_text_length(etq, fontname="hebo", fontsize=fs)
        pg.draw_rect(fitz.Rect(50, y - 17, 50 + w + 12, y + 6), color=None, fill=NEG)
        pg.insert_text((56, y), etq, fontname="hebo", fontsize=fs, color=BLA)
        pg.insert_text((50 + w + 24, y), "DE %s" % k, fontname="hebo", fontsize=fs, color=NEG)
        y += 50
        if y > 770:
            pg = doc.new_page(width=595, height=842); y = 90
    y += 10
    pg.draw_line((50, y), (545, y), color=NEG, width=1.2)
    y += 40
    pg.insert_text((55, y), "TOTAL BOLSAS:   %d" % total_bolsas, fontname="hebo", fontsize=18, color=NEG)


@app.post("/pf-despachos-sku")
def pf_despachos_sku():
    """Arranca el estampado en background (para mostrar barra de progreso) y devuelve un job id.
    El front consulta /pf-despachos-sku-progreso y baja el PDF con /pf-despachos-sku-descargar."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False}), 401
    f = request.files.get("pdf") or (next(iter(request.files.values())) if request.files else None)
    if not f:
        return jsonify({"ok": False, "msg": "subí el PDF de etiquetas"}), 400
    try:
        import fitz  # noqa: F401
    except Exception:
        return jsonify({"ok": False, "msg": "falta PyMuPDF en el servidor (esperá el redeploy)"}), 500
    data = f.read()
    import uuid
    job = uuid.uuid4().hex[:12]
    _SKU_JOBS[job] = {"done": 0, "total": 0, "msg": "Leyendo el PDF…", "listo": False,
                      "error": None, "pdf": None, "email": email, "stats": {}}
    _job_put(job, _SKU_JOBS[job])            # persisto YA → el otro worker de gunicorn ve el job
    threading.Thread(target=_sku_run, args=(job, data, email), daemon=True).start()
    return jsonify({"ok": True, "job": job})


def _sku_run(job, data, email):
    """Procesa el PDF en background, actualizando el progreso del job."""
    st = _SKU_JOBS.get(job)
    try:
        import fitz
        import io
        st["msg"] = "Sincronizando pedidos de tu tienda…"; _job_put(job, st)
        skus = _skus_map(email)                 # config de SKU por producto (lo que cargó el usuario)
        mapa = _sku_pedidos_map(email)          # {nº → nombre + productos} de Shopify + Tiendanube
        doc = fitz.open(stream=data, filetype="pdf")
        total = len(doc)
        st["total"] = total
        estampadas = conflicto = sin_pedido = 0
        detalle = []
        orden = []   # (clave, indice de pagina) -> reordenar por SKU al final (x1, x2, x3...)
        for i, pg in enumerate(doc):
            st["done"] = i
            st["msg"] = "Analizando etiqueta %d de %d…" % (i + 1, total)
            texto = pg.get_text()
            nuevo = ("Bulto" in texto) and bool(_re_and.search(r"Peso:\s*\d+\s*Gr", texto, _re_and.I))
            ped = _sku_pedido(texto, nuevo)
            cands = mapa.get(str(ped)) if ped else None
            if not cands:
                sin_pedido += 1
                detalle.append({"pedido": ped or "?", "sku": ""})
                orden.append(((999999, 0, ""), i)); continue
            # POR TIENDA: el mismo nº puede existir en Shopify Y Tiendanube → elijo por NOMBRE del destinatario.
            _lnom = _sku_label_nombre(texto)
            ent = None
            for _c in cands:
                if _sku_nombre_coincide(_lnom, _c.get("nom", "")):
                    ent = _c; break
            if ent is None:
                conflicto += 1
                detalle.append({"pedido": ped or "?", "sku": "", "conflicto": True})
                orden.append(((999998, 0, ""), i)); continue
            items = ent.get("items") or []
            unidades = sum(int(it[1] or 0) for it in items)
            sku = _sku_de_items(items, skus)
            detalle.append({"pedido": ped or "?", "sku": sku})
            if not sku:
                orden.append(((999997, 0, ""), i)); continue
            if nuevo:
                _sku_estampar_nuevo(pg, sku)
            elif "ENCOMIENDA" in texto:
                _sku_estampar_ecom(pg, sku, texto)
            else:
                _sku_estampar_std(pg, sku)
            estampadas += 1
            orden.append(((unidades, len(sku), sku), i))   # menor a mayor: por unidades, luego SKU
        st["msg"] = "Ordenando etiquetas y armando 'PARA EMPAQUETAR'…"
        orden.sort(key=lambda x: x[0])                      # x1, x2, x3... y agrupa mismos SKU
        nuevo_doc = fitz.open()
        for _clave, idx in orden:
            nuevo_doc.insert_pdf(doc, from_page=idx, to_page=idx)
        _sku_hoja_empaquetar(nuevo_doc, detalle)
        buf = io.BytesIO()
        nuevo_doc.save(buf, garbage=3, deflate=True)
        nuevo_doc.close()
        doc.close()
        st["pdf"] = buf.getvalue()
        try:
            _JOBS_DIR.mkdir(parents=True, exist_ok=True)
            (_JOBS_DIR / (job + ".pdf")).write_bytes(st["pdf"])   # PDF a disco → lo baja cualquier worker
        except Exception:
            pass
        st["done"] = total
        st["stats"] = {"total": total, "estampadas": estampadas,
                       "conflicto": conflicto, "sin_pedido": sin_pedido}
        st["msg"] = "¡Listo! %d de %d etiquetas con SKU." % (estampadas, total)
        st["listo"] = True
        _job_put(job, st)
    except Exception as e:
        import traceback as _tb
        _tbl = _tb.extract_tb(e.__traceback__)
        _ln = (" @ %s:%d" % (_tbl[-1].name, _tbl[-1].lineno)) if _tbl else ""
        st["error"] = "%s: %s%s" % (type(e).__name__, str(e)[:180], _ln)
        st["listo"] = True
        _job_put(job, st)


