_ads_local = threading.local()   # token del usuario que lanzó la subida (por thread), para no cruzar cuentas


def _ads_token():
    # 1) Si el job de subida fijó un token para ESTE thread, usá ese (cuenta correcta, sin cruces).
    t = getattr(_ads_local, "token", None)
    if t:
        return t
    # 2) Request: token que el usuario logueado PEGÓ en la app (meta_tokens.json) → env META_TOKEN.
    try:
        email = _user_actual()
    except Exception:
        email = None
    toks = _meta_tokens()
    if email and (toks.get(email) or {}).get("access_token"):
        return toks[email]["access_token"]
    for v in toks.values():
        if isinstance(v, dict) and v.get("access_token"):
            return v["access_token"]
    return _os.getenv("META_TOKEN") or ""


_ADS_TOKACCT = {}   # cache: (token[-14:], ad_account) -> bool (si ese token puede USAR esa cuenta)


def _ads_token_usa_cuenta(tok, acct):
    """¿Ese token puede administrar la cuenta publicitaria act_<acct>? (cacheado)."""
    if not tok or not acct:
        return False
    ck = (tok[-14:], str(acct))
    if ck in _ADS_TOKACCT:
        return _ADS_TOKACCT[ck]
    ok = False
    try:
        r = requests.get("%s/act_%s" % (_ADS_API, acct),
                         params={"fields": "account_status,user_tasks", "access_token": tok}, timeout=20)
        j = r.json() if r.content else {}
        # tiene la cuenta Y permiso para anunciar (no solo verla)
        ok = (r.status_code < 400 and j.get("id") and
              ("ADVERTISE" in (j.get("user_tasks") or []) or "MANAGE" in (j.get("user_tasks") or [])))
    except Exception:
        ok = False
    _ADS_TOKACCT[ck] = ok
    return ok


def _ads_token_para_cuenta(cuenta_key):
    """Devuelve el token que REALMENTE puede usar la cuenta seleccionada (no el de quien esté logueado).
    Prueba: token del usuario logueado → todos los tokens guardados → env META_TOKEN. El primero que
    tenga permiso de ADVERTISE/MANAGE sobre esa cuenta publicitaria gana. Así nunca se cruzan cuentas."""
    cfg = _ADS_CUENTAS.get(cuenta_key or "")
    acct = cfg["ad_account"] if cfg else None
    cands = []
    # 0) Token DEDICADO de la cuenta (System User que nunca vence, seteado por env). Va PRIMERO
    #    para que cada cuenta use SIEMPRE el suyo y nunca dependa del token de quien esté logueado.
    if cfg and cfg.get("token_env"):
        dedic = _os.getenv(cfg["token_env"]) or ""
        if dedic:
            cands.append(dedic)
    try:
        email = _user_actual()
    except Exception:
        email = None
    toks = _meta_tokens()
    if email and (toks.get(email) or {}).get("access_token"):
        cands.append(toks[email]["access_token"])
    for v in toks.values():
        if isinstance(v, dict) and v.get("access_token"):
            cands.append(v["access_token"])
    env = _os.getenv("META_TOKEN") or ""
    if env:
        cands.append(env)
    vistos = set()
    if acct:
        for t in cands:
            if t in vistos:
                continue
            vistos.add(t)
            if _ads_token_usa_cuenta(t, acct):
                return t
    # ninguno matchea la cuenta (o cuenta desconocida) → comportamiento viejo
    return _ads_token()


def _ads_call(method, path, data=None, files=None, params=None):
    p = dict(params or {}); p["access_token"] = _ads_token()
    r = requests.request(method, "%s/%s" % (_ADS_API, path), data=data, files=files, params=p, timeout=120)
    j = r.json() if r.content else {}
    if r.status_code >= 400:
        e = j.get("error", {})
        raise RuntimeError(e.get("error_user_msg") or e.get("message") or ("HTTP %d" % r.status_code))
    return j


def _ads_crear(acct, obj, payload):
    return _ads_call("POST", "act_%s/%s" % (acct, obj),
                     data={k: (_json.dumps(v) if isinstance(v, (dict, list)) else v)
                           for k, v in payload.items()})["id"]


def _ads_subir_video(acct, ruta):
    """Sube un video a /advideos. Grandes (>40MB) por partes (resumable)."""
    size = _os.path.getsize(ruta)
    base = "act_%s/advideos" % acct
    if size <= 40 * 1024 * 1024:
        with open(ruta, "rb") as f:
            return _ads_call("POST", base, files={"source": f})["id"]
    ini = _ads_call("POST", base, data={"upload_phase": "start", "file_size": size})
    sess, vid = ini["upload_session_id"], ini["video_id"]
    so, eo = int(ini["start_offset"]), int(ini["end_offset"])
    with open(ruta, "rb") as f:
        while so < eo:
            f.seek(so); chunk = f.read(eo - so)
            res = _ads_call("POST", base,
                            data={"upload_phase": "transfer", "upload_session_id": sess, "start_offset": so},
                            files={"video_file_chunk": ("chunk", chunk)})
            so, eo = int(res["start_offset"]), int(res["end_offset"])
    _ads_call("POST", base, data={"upload_phase": "finish", "upload_session_id": sess})
    return vid


def _ads_es_imagen(ruta):
    return ruta.lower().endswith((".jpg", ".jpeg", ".png", ".webp"))


def _ads_subir_imagen(acct, ruta):
    """Sube una imagen a /adimages y devuelve su image_hash."""
    with open(ruta, "rb") as f:
        r = _ads_call("POST", "act_%s/adimages" % acct, files={"img": f})
    imgs = r.get("images", {}) or {}
    if not imgs:
        raise RuntimeError("Meta no devolvió el hash de la imagen")
    return next(iter(imgs.values()))["hash"]


def _ads_video_ready(vid):
    import time as _t
    for _ in range(75):
        st = _ads_call("GET", str(vid), params={"fields": "status"}).get("status", {}).get("video_status")
        if st == "ready":
            return True
        if st == "error":
            return False
        _t.sleep(2.5)
    return True


def _ads_thumb(vid):
    import time as _t
    for _ in range(15):
        d = _ads_call("GET", "%s/thumbnails" % vid, params={"fields": "uri,is_preferred"}).get("data", [])
        if d:
            return ([t for t in d if t.get("is_preferred")] or d)[0]["uri"]
        _t.sleep(2)
    try:
        return _ads_call("GET", str(vid), params={"fields": "picture"}).get("picture")
    except Exception:
        return None


def _ads_start_5am():
    now = _dt.datetime.utcnow() - _dt.timedelta(hours=3)
    d = now.date() if now.hour < 5 else (now + _dt.timedelta(days=1)).date()
    return "%sT05:00:00-03:00" % d.isoformat()


def _ads_sched(params):
    """start_time del día/hora elegido; si no, próximo 5am. NUNCA en el pasado: si el horario ya
    venció (ej: lanzás 7am para el slot de 5am de hoy), lo empuja al día siguiente. Así Meta no crea
    los anuncios APAGADOS por un horario vencido."""
    f = (params.get("fecha") or "").strip()
    h = (params.get("hora") or "05:00").strip()
    if len(h) != 5:
        h = "05:00"
    ahora = _dt.datetime.utcnow() - _dt.timedelta(hours=3)          # hora AR
    if f:
        try:
            y, mo, da = (int(x) for x in f.split("-"))
            dt = _dt.datetime(y, mo, da, int(h[:2]), int(h[3:5]))
        except Exception:
            return _ads_start_5am()
    else:
        dt = ahora.replace(hour=5, minute=0, second=0, microsecond=0)
    while dt <= ahora + _dt.timedelta(minutes=5):                   # ya pasó → al día siguiente
        dt += _dt.timedelta(days=1)
    return dt.strftime("%Y-%m-%dT%H:%M:00-03:00")


def _ads_camp_payload(nombre, cbo, presup, status, budget_sharing=False):
    p = {"name": nombre, "objective": "OUTCOME_SALES", "special_ad_categories": [],
         "buying_type": "AUCTION", "status": status}
    if cbo:
        p["daily_budget"] = int(presup) * 100
        p["bid_strategy"] = "LOWEST_COST_WITHOUT_CAP"   # CBO: la estrategia de puja va en la campaña (que tiene presupuesto)
    else:
        # ABO: el presupuesto y la estrategia de puja van en cada CONJUNTO, NO en la campaña
        # (sin presupuesto de campaña, Meta rechaza el bid_strategy acá). Solo declaramos el compartir.
        p["is_adset_budget_sharing_enabled"] = bool(budget_sharing)
    return p


def _ads_adset_payload(nombre, campaign_id, pixel, cbo, presup, status, start=None):
    p = {"name": nombre, "campaign_id": campaign_id, "billing_event": "IMPRESSIONS",
         "optimization_goal": "OFFSITE_CONVERSIONS",
         "promoted_object": {"pixel_id": pixel, "custom_event_type": "PURCHASE"},
         "attribution_spec": [{"event_type": "CLICK_THROUGH", "window_days": 7},
                              {"event_type": "VIEW_THROUGH", "window_days": 1}],
         "targeting": {"geo_locations": {"countries": ["AR"]},
                       "targeting_automation": {"advantage_audience": 1}},
         "status": status}
    if not cbo:
        p["daily_budget"] = int(presup) * 100        # ABO: presupuesto por conjunto
        p["bid_strategy"] = "LOWEST_COST_WITHOUT_CAP"  # ABO: la estrategia de puja va en el conjunto
    if status == "ACTIVE":
        p["start_time"] = start or _ads_start_5am()
    return p


def _ads_creative_payload(nombre, medio, cfg, ad):
    """medio: {'kind':'video','video_id','thumb'} o {'kind':'image','image_hash'}.
    ad: {copy, titulo, subtitulo, url} (cae a los defaults de la cuenta)."""
    url = (ad.get("url") or "").strip() or cfg["landing"]
    cta = {"type": "SHOP_NOW", "value": {"link": url}}
    title = (ad.get("titulo") or cfg.get("titulo") or "")
    msg = ad.get("copy") or cfg["copy"]
    _sub = (ad.get("subtitulo") or "").strip() or (cfg.get("subtitulo") or "").strip()
    if medio.get("kind") == "image":
        ld = {"image_hash": medio["image_hash"], "link": url, "message": msg,
              "name": title, "call_to_action": cta}
        if _sub:
            ld["description"] = _sub
        oss = {"page_id": cfg["page"], "link_data": ld}
    else:
        vd = {"video_id": medio["video_id"], "message": msg,
              "call_to_action": cta, "title": title}
        if _sub:
            vd["link_description"] = _sub
        if medio.get("thumb"):
            vd["image_url"] = medio["thumb"]
        oss = {"page_id": cfg["page"], "video_data": vd}
    creative = {"name": nombre, "object_story_spec": oss,
                # Multianunciante OFF + sin mejoras automáticas. OJO: NO mandar "standard_enhancements"
                # (Meta lo deprecó y RECHAZA la creación: "elige configurar funciones individuales").
                "contextual_multi_ads": {"enroll_status": "OPT_OUT"},
                "degrees_of_freedom_spec": {"creative_features_spec": {
                    "site_extensions": {"enroll_status": "OPT_OUT"}}}}
    if cfg.get("ig"):
        creative["instagram_user_id"] = cfg["ig"]   # el IG va al NIVEL del creativo, no dentro de object_story_spec
    return creative


def _ads_adset_dup(acct, src_id, campaign_id, nombre, pixel, status, start=None, presup_override=None):
    """Crea un conjunto NUEVO copiando la config de src_id (segmentación/optimización/pixel/atribución),
    vacío. No copia los ads viejos. Filtra placeholders que Meta rechaza (UNDEFINED/NONE).
    presup_override: si viene (ABO), fija ese presupuesto diario en vez de copiar el del origen."""
    F = ("name,billing_event,optimization_goal,targeting,promoted_object,attribution_spec,"
         "destination_type,optimization_sub_event,pacing_type,daily_budget")
    s = _ads_call("GET", str(src_id), params={"fields": F})
    p = {"name": nombre or (s.get("name", "CONJUNTO") + " copia"), "campaign_id": campaign_id,
         "billing_event": s.get("billing_event") or "IMPRESSIONS",
         "optimization_goal": s.get("optimization_goal") or "OFFSITE_CONVERSIONS",
         "targeting": s.get("targeting") or {"geo_locations": {"countries": ["AR"]},
                                             "targeting_automation": {"advantage_audience": 1}},
         "status": status}
    if s.get("promoted_object"):
        p["promoted_object"] = s["promoted_object"]
    elif pixel:
        p["promoted_object"] = {"pixel_id": pixel, "custom_event_type": "PURCHASE"}
    if s.get("attribution_spec"):
        p["attribution_spec"] = s["attribution_spec"]
    if s.get("destination_type") and s["destination_type"] != "UNDEFINED":
        p["destination_type"] = s["destination_type"]
    if s.get("optimization_sub_event") not in (None, "", "NONE"):
        p["optimization_sub_event"] = s["optimization_sub_event"]
    if s.get("pacing_type"):
        p["pacing_type"] = s["pacing_type"]
    _po = None
    try:
        _po = int(round(float(presup_override))) if (presup_override not in (None, "", 0, "0")) else None
    except Exception:
        _po = None
    if _po:                                          # ABO: presupuesto que puso el usuario a mano
        p["daily_budget"] = _po * 100
        p["bid_strategy"] = "LOWEST_COST_WITHOUT_CAP"
    elif s.get("daily_budget"):
        p["daily_budget"] = s["daily_budget"]        # ABO: copia el presupuesto del conjunto origen
        p["bid_strategy"] = "LOWEST_COST_WITHOUT_CAP"  # ABO: la estrategia de puja va en el conjunto
    if status == "ACTIVE":
        p["start_time"] = start or _ads_start_5am()
    return _ads_crear(acct, "adsets", p)


def _ads_google_creds():
    from google.oauth2 import service_account
    scopes = ["https://www.googleapis.com/auth/drive.readonly"]
    raw = _os.getenv("GOOGLE_SERVICE_ACCOUNT_JSON")
    if raw:
        return service_account.Credentials.from_service_account_info(_json.loads(raw), scopes=scopes)
    fp = _os.getenv("GOOGLE_SERVICE_ACCOUNT_FILE") or str(RAIZ / "service-account.json")
    return service_account.Credentials.from_service_account_file(fp, scopes=scopes)


def _fin_sheets_creds():
    """Credenciales del MISMO service account pero con scope de ESCRITURA en Sheets
    (el de Drive es readonly). Sirve para que el bot de finanzas complete la planilla."""
    from google.oauth2 import service_account
    scopes = ["https://www.googleapis.com/auth/spreadsheets"]
    raw = _os.getenv("GOOGLE_SERVICE_ACCOUNT_JSON")
    if raw:
        return service_account.Credentials.from_service_account_info(_json.loads(raw), scopes=scopes)
    fp = _os.getenv("GOOGLE_SERVICE_ACCOUNT_FILE") or str(RAIZ / "service-account.json")
    return service_account.Credentials.from_service_account_file(fp, scopes=scopes)


def _fin_sheet_id(link):
    """Saca el ID de un link de Google Sheets (o devuelve lo pegado si ya es el ID)."""
    m = _re_and.search(r"/spreadsheets/d/([A-Za-z0-9_-]+)", link or "")
    return m.group(1) if m else (link or "").strip()


@app.get("/fin-sheet-peek")
def fin_sheet_peek():
    """DIAGNOSTICO: lee la planilla de finanzas con el service account.
    Confirma que el acceso funciona (compartida + API habilitada) y devuelve la
    estructura real (pestañas + fórmulas vs valores) para mapear qué columnas se cargan."""
    from urllib.parse import quote as _q
    from google.auth.transport.requests import AuthorizedSession
    if not _user_actual():
        return jsonify({"ok": False, "msg": "sin sesion"}), 401
    sid = _fin_sheet_id(request.args.get("id") or "")
    rng = (request.args.get("rango") or "").strip()
    if not sid:
        return jsonify({"ok": False, "msg": "falta id"})
    try:
        sess = AuthorizedSession(_fin_sheets_creds())
        base = "https://sheets.googleapis.com/v4/spreadsheets/" + sid
        m = sess.get(base, params={"fields": "properties.title,sheets.properties"}, timeout=(15, 45))
        if m.status_code != 200:
            return jsonify({"ok": False, "paso": "meta", "code": m.status_code, "det": m.text[:700]})
        mj = m.json()
        out = {"ok": True, "titulo": (mj.get("properties") or {}).get("title"), "pestanas": []}
        for s in (mj.get("sheets") or []):
            p = s.get("properties") or {}
            g = p.get("gridProperties") or {}
            out["pestanas"].append({"gid": p.get("sheetId"), "nombre": p.get("title"),
                                    "filas": g.get("rowCount"), "cols": g.get("columnCount")})
        if rng:
            for tipo in ("FORMULA", "FORMATTED_VALUE"):
                r = sess.get(base + "/values/" + _q(rng, safe=""),
                             params={"valueRenderOption": tipo}, timeout=(15, 45))
                out[tipo.lower()] = (r.json().get("values") if r.status_code == 200
                                     else "ERR %s %s" % (r.status_code, r.text[:300]))
        return jsonify(out)
    except Exception as e:
        return jsonify({"ok": False, "msg": "%s: %s" % (type(e).__name__, e)})


# ============ BOT FINANZAS: completa la planilla "RENTABILIDAD DIARIA" ============
# Escribe SOLO las columnas de carga (B Fecha, C Día, D Ventas, E Unidades, H Facturado,
# J Ingreso Limpio, R ADS USD). Todo lo demás de la planilla son fórmulas → NO se tocan.
_FIN_MES = ["ENERO", "FEBRERO", "MARZO", "ABRIL", "MAYO", "JUNIO", "JULIO", "AGOSTO",
            "SEPTIEMBRE", "OCTUBRE", "NOVIEMBRE", "DICIEMBRE"]
_FIN_DIA = ["Lunes", "Martes", "Miércoles", "Jueves", "Viernes", "Sábado", "Domingo"]
_FIN_FILE = DATA_DIR / "fin_sheet.json"     # {email: {"sheet": id, "desde": "2026-08-05", "auto": true}}
_FIN_EPOCH = _dt.date(1899, 12, 30)         # día 0 de los seriales de Google Sheets
_FIN_FILA0 = 5                              # fila 6 = día 1  →  fila = día + 5


def _fin_conf() -> dict:
    try:
        return _json.loads(_FIN_FILE.read_text("utf-8"))
    except Exception:
        return {}


def _fin_conf_save(d) -> None:
    try:
        _FIN_FILE.write_text(_json.dumps(d, ensure_ascii=False, indent=1), "utf-8")
    except Exception:
        pass


def _fin_hoy_ar():
    """Fecha de HOY en hora Argentina (el server corre en UTC)."""
    return (_dt.datetime.utcnow() - _dt.timedelta(hours=3)).date()


def _fin_ads_usd(email, desde, hasta) -> float:
    """Gasto REAL de Meta en USD del período, SUMANDO todas las cuentas de la tienda (CP1 + CP2).
    Ojo: _meta_spend devuelve ARS (convierte con el dólar vivo). Acá va el USD crudo porque la
    planilla lo pasa a pesos sola (columna ADS ARS = ADS USD × T.C de D3)."""
    tk = _meta_tokens().get(email)
    token = tk.get("access_token") if tk else None
    cuenta = tk.get("cuenta") if tk else None
    if not token:
        owner = _os.getenv("META_OWNER_EMAIL", "").strip().lower()
        if owner and email and email.strip().lower() == owner and _os.getenv("META_OWNER_TOKEN"):
            token = _os.getenv("META_OWNER_TOKEN")
            cuenta = _os.getenv("META_OWNER_ACT") or cuenta
    if not token or not cuenta:
        return 0.0
    primaria = str(cuenta).replace("act_", "").strip()
    cuentas = [primaria] if primaria else []
    for grupo in (_os.getenv("META_ACTS_EXTRA", "") or "").split(";"):
        if ":" not in grupo:
            continue
        pri, extras = grupo.split(":", 1)
        if pri.strip().replace("act_", "") != primaria:
            continue                     # grupo de OTRA tienda → no sumar
        for ex in extras.split(","):
            ex = ex.strip().replace("act_", "")
            if ex and ex not in cuentas:
                cuentas.append(ex)
    total = 0.0
    for acc in cuentas:
        try:
            r = requests.get("https://graph.facebook.com/%s/act_%s/insights" % (META_API, acc),
                             params={"access_token": token, "fields": "spend,account_currency",
                                     "time_range": _json.dumps({"since": desde, "until": hasta}),
                                     "level": "account"}, timeout=30)
            data = r.json().get("data") or []
            if not data:
                continue
            spend = float(data[0].get("spend") or 0)
            moneda = (data[0].get("account_currency") or "").upper()
            if moneda and moneda != "USD":       # cuenta en pesos → lo paso a USD con el dólar vivo
                tc = _dolar_ars_vivo() or 0
                spend = (spend / tc) if tc else 0.0
            total += spend
        except Exception:
            pass
    return round(total, 2)


def _fin_mp_entrada(email, f) -> dict:
    """LIQUIDACIONES de MercadoPago de ese día: suma del NETO de los pagos cuya PLATA SE
    LIBERÓ ese día (money_release_date), o sea lo que de verdad entró a la cuenta.
    OJO: NO es date_approved — un pago se aprueba un día y la plata se libera otro (cuotas,
    transferencias, retención de MP). Aprobado ≠ disponible. Es un reporte de caja, no un
    cálculo sobre los pedidos.""" 
    d = f.strftime("%Y-%m-%d") if hasattr(f, "strftime") else str(f)[:10]
    pagos = []
    fr = _mp_freeze_all().get(email)
    fe = _mp_freeze_end(email) or FREEZE_END
    if fr and d <= fe:                     # histórico congelado, por fecha de LIBERACIÓN
        pagos = [p for p in fr if (p.get("money_release_date") or "")[:10] == d]
    else:                                  # en vivo contra la API de MP, ese día exacto
        tk = _mp_tokens().get(email)
        token = tk.get("access_token") if tk else None
        if not token:
            return {"ok": False, "bruto": 0.0, "neto": 0.0, "pagos": 0}
        offset = 0
        try:
            while True:
                r = requests.get("https://api.mercadopago.com/v1/payments/search",
                                 headers={"Authorization": "Bearer " + token},
                                 params={"sort": "date_approved", "criteria": "desc",
                                         "range": "money_release_date",
                                         "begin_date": d + "T00:00:00.000-03:00",
                                         "end_date": d + "T23:59:59.999-03:00",
                                         "status": "approved", "offset": offset, "limit": 100},
                                 timeout=30)
                if r.status_code >= 400:
                    if offset == 0:
                        return {"ok": False, "bruto": 0.0, "neto": 0.0, "pagos": 0}
                    break
                j = r.json()
                res = j.get("results") or []
                pagos.extend(res)
                offset += 100
                if offset >= (j.get("paging") or {}).get("total", 0) or not res:
                    break
        except Exception:
            return {"ok": False, "bruto": 0.0, "neto": 0.0, "pagos": 0}
    # Solo las liquidaciones de VENTAS: los pagos de un checkout traen external_reference
    # (el nº de pedido). Los que no la traen es plata que entró por otra vía a esa misma cuenta
    # de MP (otra tienda, transferencias sueltas, etc.) y NO corresponde a esta operación.
    bruto = neto = 0.0
    bruto_otros = neto_otros = 0.0
    n_venta = n_otros = 0
    for p in pagos:
        ta = float(p.get("transaction_amount") or 0)
        nt = float((p.get("transaction_details") or {}).get("net_received_amount") or 0)
        if not nt:                          # sin neto informado → bruto menos las comisiones
            nt = ta - sum(float(x.get("amount") or 0) for x in (p.get("fee_details") or []))
        if (p.get("external_reference") or "").strip():
            bruto += ta; neto += nt; n_venta += 1
        else:
            bruto_otros += ta; neto_otros += nt; n_otros += 1
    return {"ok": True, "bruto": round(bruto, 2), "neto": round(neto, 2), "pagos": n_venta,
            "otros_bruto": round(bruto_otros, 2), "otros_neto": round(neto_otros, 2),
            "otros_pagos": n_otros}


def _fin_datos_dia(email, f) -> dict:
    """Los números reales del día ya cerrado, para la fila de ese día."""
    d = f.strftime("%Y-%m-%d")
    res = _shopify_resumen(email, d, d) or {}
    raw = res.get("raw") or {}
    fact = float(raw.get("facturado") or 0)
    # INGRESO LIMPIO = suma del NETO de los pagos DE LAS ÓRDENES DE ESE DÍA.
    # RealProfit matchea cada pedido con su pago de MP (por referencia; si no, por monto exacto) y
    # usa el neto real de ESE pago. Los que no matchean entran al 100% (transferencia directa).
    # NO se usa la liquidación diaria de MP: esa mezcla pagos de otros días y da comisiones
    # negativas (pasó: -36%, -56%), porque el ingreso y el facturado quedan en marcos distintos.
    mp = {"ok": False, "bruto": 0.0, "pagos": int(raw.get("mp_match") or 0)}
    limpio = fact - float(raw.get("mp_costo_real") or 0)
    # OXIDO NITRICO: va de REGALO con el pack de 6 potes, pero igual figura como un renglon mas
    # en la orden de Shopify. Se cuenta en UNIDADES (ya venia contado) y en COSTO, pero a SU
    # precio (M49), no al del NAD (N49) — si no, cada regalo se costea de mas.
    ox = 0
    for _p in (res.get("prod") or []):
        _n = str(_p.get("nombre") or "").lower()
        if "xido" in _n and "trico" in _n:
            ox += int(_p.get("unidades") or 0)
    return {"fecha": d,
            "ventas": int(raw.get("ordenes") or 0),
            "unidades": int(raw.get("unidades") or 0),
            "unidades_ox": ox,
            "facturado": round(fact, 2),
            "ingreso_limpio": round(limpio, 2),
            "mp_bruto": mp.get("bruto", 0.0), "mp_pagos": mp.get("pagos", 0),
            "mp_otros_neto": mp.get("otros_neto", 0.0), "mp_otros_pagos": mp.get("otros_pagos", 0),
            "mp_fuente": "MP x orden",
            # ENVÍO: la tabla Andreani por ZONA con el descuento propio (provincia/CP + sucursal
            # vs domicilio), la misma que usa RealProfit. La planilla traía "=5200*pedidos" (estimado).
            "envio": round(float(raw.get("envio_zona_monto") or 0), 2),
            # IIBB como lo calcula RealProfit (3,5% configurable), no el 2% que traía la planilla.
            "iibb": round(float(raw.get("iibb_monto") or 0), 2),
            "ads_usd": _fin_ads_usd(email, d, d)}


# Fórmulas de las filas de cierre que venían MAL en la planilla y el bot repara.
# Solo lo roto: rangos cortados (6:33 / 6:35 en vez de 6:36 → se perdían los últimos
# días del mes) y la fila TOTAL USD que dividía por $C$1 (vacía → #DIV/0!) en vez del T.C de $D$3.
# NO se tocan W40/X40 (tienen ajustes propios) ni M41 (=M40/D40).
_FIN_TOTALES = {
    40: {"D": "=SUM(D6:D36)", "E": "=SUM(E6:E36)", "F": "=SUM(F6:F36)", "G": "=SUM(G6:G36)",
         "H": "=SUM(H6:H36)", "J": "=SUM(J6:J36)", "K": "=AVERAGE(K6:K36)", "M": "=SUM(M6:M36)",
         "P": "=SUM(P6:P36)", "S": "=SUM(S6:S36)", "T": "=SUM(T6:T36)", "Z": "=AVERAGE(Z6:Z36)"},
    41: {"D": "=AVERAGE(D6:D36)", "E": "=AVERAGE(E6:E36)", "F": "=AVERAGE(F6:F36)",
         "G": "=AVERAGE(G6:G36)", "H": "=AVERAGE(H6:H36)", "J": "=AVERAGE(J6:J36)",
         "R": "=AVERAGE(R6:R36)", "S": "=AVERAGE(S6:S36)", "T": "=AVERAGE(T6:T36)",
         "W": "=AVERAGE(W6:W36)", "Y": "=AVERAGE(Y6:Y36)"},
    42: {"F": "=F40/$D$3", "G": "=G40/$D$3", "H": "=H40/$D$3", "J": "=J40/$D$3",
         "M": "=M40/$D$3", "S": "=S40/$D$3", "T": "=T40/$D$3", "W": "=W40/$D$3",
         "Y": "=Y40/$D$3"},
}


def _fin_reparar_totales(sess, sid, tab) -> None:
    """Corrige las filas TOTAL ARS / PROMEDIO / TOTAL USD, y deja el Fulfill del mes al día."""
    data = [{"range": "%s!%s%d" % (tab, col, fila), "values": [[fx]]}
            for fila, cols in _FIN_TOTALES.items() for col, fx in cols.items()]
    # Fulfill = SOLO el armado ($800/pedido). Los INSUMOS no van acá: el dueño los carga una vez
    # al mes en la sección Gastos de la planilla, así no se cuentan dos veces.
    # (En RealProfit sí van juntos —$1.000— porque ahí no hay una carga mensual de gastos.)
    data += [{"range": "%s!T%d" % (tab, f), "values": [["=%d*D%d" % (FULFILLMENT_ORDEN, f)]]}
             for f in range(6, 37)]
    try:
        sess.post("https://sheets.googleapis.com/v4/spreadsheets/%s/values:batchUpdate" % sid,
                  json={"valueInputOption": "USER_ENTERED", "data": data}, timeout=(15, 90))
    except Exception:
        pass


def _fin_formato_unidades(sess, sid, tab, gid) -> None:
    """Le da a la columna Unidades (E) el MISMO formato/color que Ventas Totales (D),
    encabezado incluido, y la DESOCULTA (venía escondida en la planilla, por eso no se veía).
    Solo formato/visibilidad: no toca ningún valor."""
    try:
        sess.post("https://sheets.googleapis.com/v4/spreadsheets/%s:batchUpdate" % sid,
                  json={"requests": [
                      {"updateDimensionProperties": {          # mostrar la columna E (Unidades)
                          "range": {"sheetId": gid, "dimension": "COLUMNS",
                                    "startIndex": 4, "endIndex": 5},
                          "properties": {"hiddenByUser": False}, "fields": "hiddenByUser"}},
                      {"copyPaste": {
                      "source": {"sheetId": gid, "startRowIndex": 4, "endRowIndex": 36,
                                 "startColumnIndex": 3, "endColumnIndex": 4},
                      "destination": {"sheetId": gid, "startRowIndex": 4, "endRowIndex": 36,
                                      "startColumnIndex": 4, "endColumnIndex": 5},
                       "pasteType": "PASTE_FORMAT"}}]}, timeout=(15, 60))
    except Exception:
        pass


def _fin_sess():
    from google.auth.transport.requests import AuthorizedSession
    return AuthorizedSession(_fin_sheets_creds())


def _fin_tabs(sess, sid) -> dict:
    """{nombre de pestaña: gid}"""
    r = sess.get("https://sheets.googleapis.com/v4/spreadsheets/" + sid,
                 params={"fields": "sheets.properties"}, timeout=(15, 45))
    if r.status_code != 200:
        raise RuntimeError("no pude leer la planilla (%s): %s" % (r.status_code, r.text[:200]))
    out = {}
    for s in (r.json().get("sheets") or []):
        p = s.get("properties") or {}
        out[p.get("title")] = p.get("sheetId")
    return out


def _fin_tab_mes(sess, sid, f) -> str:
    """Nombre de la pestaña del mes de `f`. Si no existe la CREA duplicando la última que haya
    (se copia con todas las fórmulas y el formato) y la deja lista: fechas y días del mes
    escritos, y las columnas de carga en blanco."""
    nombre = "MES " + _FIN_MES[f.month - 1]
    tabs = _fin_tabs(sess, sid)
    if nombre in tabs:
        return nombre
    if not tabs:
        raise RuntimeError("la planilla no tiene ninguna pestaña para copiar")
    base_gid = list(tabs.values())[-1]        # duplico la última (trae fórmulas y formato)
    r = sess.post("https://sheets.googleapis.com/v4/spreadsheets/%s:batchUpdate" % sid,
                  json={"requests": [{"duplicateSheet": {
                      "sourceSheetId": base_gid, "newSheetName": nombre,
                      "insertSheetIndex": len(tabs)}}]}, timeout=(15, 60))
    if r.status_code != 200:
        raise RuntimeError("no pude crear la pestaña %s: %s" % (nombre, r.text[:200]))
    import calendar as _cal
    ndias = _cal.monthrange(f.year, f.month)[1]
    data = []
    for d in range(1, ndias + 1):
        fecha = _dt.date(f.year, f.month, d)
        fila = d + _FIN_FILA0
        data.append({"range": "%s!B%d:E%d" % (nombre, fila, fila),
                     "values": [[(fecha - _FIN_EPOCH).days, _FIN_DIA[fecha.weekday()], "", ""]]})
        data.append({"range": "%s!H%d" % (nombre, fila), "values": [[""]]})
        data.append({"range": "%s!J%d" % (nombre, fila), "values": [[""]]})
        data.append({"range": "%s!R%d" % (nombre, fila), "values": [[""]]})
    sess.post("https://sheets.googleapis.com/v4/spreadsheets/%s/values:batchUpdate" % sid,
              json={"valueInputOption": "RAW", "data": data}, timeout=(15, 90))
    return nombre


def _fin_cargar_dia(email, f) -> dict:
    """Calcula el día y lo escribe en la fila que le toca. Idempotente (se puede repetir).
    De paso deja el formato de plata en la columna de GASTOS (se auto-repara cada noche)."""
    conf = (_fin_conf().get(email) or {})
    sid = conf.get("sheet")
    if not sid:
        return {"ok": False, "msg": "esta cuenta no tiene planilla configurada"}
    dat = _fin_datos_dia(email, f)
    sess = _fin_sess()
    tab = _fin_tab_mes(sess, sid, f)
    _gastos_formato(sess, sid, tab)      # deja la columna de GASTOS como plata ($ 1.234.567)
    fila = f.day + _FIN_FILA0
    # RAW: números y textos tal cual (no pisa el formato de fecha de la celda)
    r = sess.post("https://sheets.googleapis.com/v4/spreadsheets/%s/values:batchUpdate" % sid,
                  json={"valueInputOption": "RAW", "data": [
                      {"range": "%s!B%d:E%d" % (tab, fila, fila),
                       "values": [[(f - _FIN_EPOCH).days, _FIN_DIA[f.weekday()],
                                   dat["ventas"], dat["unidades"]]]},
                      {"range": "%s!H%d" % (tab, fila), "values": [[dat["facturado"]]]},
                      {"range": "%s!J%d" % (tab, fila), "values": [[dat["ingreso_limpio"]]]},
                      {"range": "%s!R%d" % (tab, fila), "values": [[dat["ads_usd"]]]},
                  ]}, timeout=(15, 90))
    if r.status_code != 200:
        return {"ok": False, "msg": "error escribiendo: %s %s" % (r.status_code, r.text[:250])}
    # ENVÍO REAL + RÉGIMEN. Van en RAW (números), pisando las fórmulas estimadas.
    regimen = str(conf.get("regimen") or "monotributo").lower()
    extra = [{"range": "%s!M%d" % (tab, fila), "values": [[dat["envio"]]]},
             {"range": "%s!Y%d" % (tab, fila), "values": [[dat["iibb"]]]}]
    if regimen.startswith("mono"):
        # MONOTRIBUTO: no hay IVA (ni crédito, ni débito, ni a pagar). Si estas columnas quedan
        # con las fórmulas de Responsable Inscripto, la Ganancia Neta (=J-F-M-S-X-Y-T) resta un
        # "IVA a pagar" que NO se paga y la ganancia queda subestimada. Por eso van en 0.
        for col in ("G", "I", "L", "N", "Q", "U", "V", "X"):
            extra.append({"range": "%s!%s%d" % (tab, col, fila), "values": [[0]]})
    sess.post("https://sheets.googleapis.com/v4/spreadsheets/%s/values:batchUpdate" % sid,
              json={"valueInputOption": "RAW", "data": extra}, timeout=(15, 90))
    # COSTO MERCADERIA = UNIDADES × precio, PARTIDO POR PRODUCTO. Arreglos sobre la planilla:
    #  1) usaba N49/N50/N51 (referencia relativa que se desliza a celdas vacías → costo $0);
    #  2) multiplicaba por D (PEDIDOS), pero si un pedido lleva 3 potes el costo son 3;
    #  3) costeaba TODO a $N$49 (precio del NAD), incluido el Óxido Nítrico que va de regalo
    #     con el pack de 6 → cada regalo se cargaba $6.300 en vez de $5.500.
    # Queda "=<potes NAD>*$N$49 + <oxido>*$M$49": las cantidades salen de Shopify y los precios
    # siguen en la planilla, así se pueden cambiar sin tocar código.
    _ox = int(dat.get("unidades_ox") or 0)
    _nad = max(int(dat.get("unidades") or 0) - _ox, 0)
    _fx = ("=%d*$N$49+%d*$M$49" % (_nad, _ox)) if _ox else ("=%d*$N$49" % _nad)
    sess.post("https://sheets.googleapis.com/v4/spreadsheets/%s/values:batchUpdate" % sid,
              json={"valueInputOption": "USER_ENTERED",
                    "data": [{"range": "%s!F%d" % (tab, fila),
                              "values": [[_fx]]}]}, timeout=(15, 60))
    dat.update({"ok": True, "pestana": tab, "fila": fila, "regimen": regimen})
    return dat


def _fin_bot_loop():
    """Todos los días ~1:15am (hora AR) carga el día que cerró, por cada cuenta configurada."""
    import time as _t
    while True:
        try:
            ahora = _dt.datetime.utcnow() - _dt.timedelta(hours=3)
            prox = ahora.replace(hour=1, minute=15, second=0, microsecond=0)
            if prox <= ahora:
                prox += _dt.timedelta(days=1)
            _t.sleep(max(60.0, (prox - ahora).total_seconds()))
            ayer = _fin_hoy_ar() - _dt.timedelta(days=1)
            for email, c in (_fin_conf() or {}).items():
                if not c.get("sheet") or c.get("auto") is False:
                    continue
                try:
                    _fin_cargar_dia(email, ayer)
                except Exception:
                    pass
        except Exception:
            _t.sleep(300)


@app.post("/fin-config")
def fin_config():
    """Guarda (o apaga) la planilla de finanzas de la cuenta logueada."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesion"}), 401
    d = request.get_json(silent=True) or {}
    conf = _fin_conf()
    c = conf.get(email) or {}
    if d.get("sheet") is not None:
        c["sheet"] = _fin_sheet_id(d.get("sheet") or "")
    if d.get("desde"):
        c["desde"] = str(d["desde"])[:10]
    if d.get("auto") is not None:
        c["auto"] = bool(d["auto"])
    if d.get("regimen"):                 # "monotributo" (sin IVA) o "ri" (Responsable Inscripto)
        c["regimen"] = str(d["regimen"]).lower()
    conf[email] = c
    _fin_conf_save(conf)
    return jsonify({"ok": True, "conf": c})


@app.post("/fin-cargar")
def fin_cargar():
    """Carga a mano uno o varios días: {"desde":"2026-08-05","hasta":"2026-09-02"}
    (sin fechas = el día que cerró ayer)."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesion"}), 401
    d = request.get_json(silent=True) or {}
    try:
        if d.get("desde"):
            f1 = _dt.datetime.strptime(str(d["desde"])[:10], "%Y-%m-%d").date()
            f2 = _dt.datetime.strptime(str(d.get("hasta") or d["desde"])[:10], "%Y-%m-%d").date()
        else:
            f1 = f2 = _fin_hoy_ar() - _dt.timedelta(days=1)
    except Exception:
        return jsonify({"ok": False, "msg": "fecha invalida (usar YYYY-MM-DD)"})
    if (f2 - f1).days > 92:
        return jsonify({"ok": False, "msg": "rango muy largo (max 92 dias)"})
    hechos, errores = [], []
    f = f1
    while f <= f2:
        try:
            r = _fin_cargar_dia(email, f)
            (hechos if r.get("ok") else errores).append(r if r.get("ok") else
                                                        {"fecha": f.strftime("%Y-%m-%d"), "msg": r.get("msg")})
        except Exception as e:
            errores.append({"fecha": f.strftime("%Y-%m-%d"), "msg": "%s: %s" % (type(e).__name__, e)})
        f += _dt.timedelta(days=1)
    # una sola vez por pestaña tocada: Unidades queda con el mismo formato que Ventas
    try:
        sid = ((_fin_conf().get(email) or {}).get("sheet"))
        if sid and hechos:
            sess = _fin_sess()
            gids = _fin_tabs(sess, sid)
            for tab in {h.get("pestana") for h in hechos if h.get("pestana")}:
                if tab in gids:
                    _fin_formato_unidades(sess, sid, tab, gids[tab])
                    _fin_reparar_totales(sess, sid, tab)
    except Exception:
        pass
    return jsonify({"ok": not errores, "cargados": len(hechos), "dias": hechos, "errores": errores})


def _ads_drive_fid(link):
    m = _re_and.search(r"/folders/([A-Za-z0-9_-]+)", link or "")
    if m:
        return m.group(1)
    m = _re_and.search(r"[?&]id=([A-Za-z0-9_-]+)", link or "")
    return m.group(1) if m else (link or "").strip()


def _ads_drive_files(link):
    """Lista los archivos (video/imagen) de la carpeta por REST directo CON TIMEOUT.
    Reemplaza a googleapiclient (que NO tiene timeout y se colgaba para siempre si Google/Render
    se trababa → el subidor quedaba en 'Bajando videos de Drive…' sin error ni progreso)."""
    from google.auth.transport.requests import AuthorizedSession
    sess = AuthorizedSession(_ads_google_creds())
    fid = _ads_drive_fid(link)
    params = {"q": "'%s' in parents and trashed=false" % fid,
              "fields": "files(id,name,mimeType,size),nextPageToken",
              "supportsAllDrives": "true", "includeItemsFromAllDrives": "true",
              "orderBy": "name", "pageSize": "100"}
    files = []
    tok = None
    for _ in range(12):
        if tok:
            params["pageToken"] = tok
        r = sess.get("https://www.googleapis.com/drive/v3/files", params=params, timeout=(15, 45))
        r.raise_for_status()
        j = r.json()
        files += j.get("files", [])
        tok = j.get("nextPageToken")
        if not tok:
            break
    vids = [f for f in files if "video" in (f.get("mimeType") or "") or "image" in (f.get("mimeType") or "")
            or f.get("name", "").lower().endswith((".mp4", ".mov", ".m4v", ".jpg", ".jpeg", ".png", ".webp"))]
    vids.sort(key=lambda f: f.get("name", ""))
    return vids


def _ads_drive_listar(link):
    """Lista los videos de la carpeta (sin bajarlos) para el botón 'Buscar videos'."""
    return [{"name": f.get("name", ""),
             "mb": round(int(f.get("size") or 0) / 1048576) if f.get("size") else 0}
            for f in _ads_drive_files(link)]


def _ads_drive_bajar(link, dest_dir, on_prog=None):
    """Baja los videos/imágenes de la carpeta EN PARALELO por HTTP directo con timeout por archivo
    y TOPE TOTAL. Cualquier traba tira error claro (nunca spinner infinito)."""
    import concurrent.futures as _cf
    import time as _t
    from google.auth.transport.requests import AuthorizedSession
    vids = _ads_drive_files(link)          # ya viene con timeout; si Drive no responde, tira error acá
    if not vids:
        return []
    if on_prog:
        on_prog(0, len(vids))              # avisar YA cuántos son (mejor feedback que 'Bajando…' pelado)
    creds = _ads_google_creds()
    _dl = {"n": 0}
    _lk = threading.Lock()

    def _bajar_uno(f):
        sess = AuthorizedSession(creds)     # sesión propia por thread
        p = _os.path.join(dest_dir, f["name"])
        url = "https://www.googleapis.com/drive/v3/files/%s?alt=media&supportsAllDrives=true" % f["id"]
        # timeout=(conexión 15s, lectura 60s SIN bytes): si Google/Render se cuelga, TIRA ERROR
        with sess.get(url, stream=True, timeout=(15, 60)) as r:
            r.raise_for_status()
            with open(p, "wb") as fh:
                for chunk in r.iter_content(chunk_size=1024 * 1024 * 4):
                    if chunk:
                        fh.write(chunk)
        with _lk:
            _dl["n"] += 1
            if on_prog:
                on_prog(_dl["n"], len(vids))
        return p

    out = [None] * len(vids)
    # 4 en paralelo (antes 8): menos contención de red/RAM en Render. Tope total 8 min → error claro.
    with _cf.ThreadPoolExecutor(max_workers=min(4, max(1, len(vids)))) as _ex:
        futs = {_ex.submit(_bajar_uno, f): i for i, f in enumerate(vids)}
        try:
            for fut in _cf.as_completed(futs, timeout=480):
                out[futs[fut]] = fut.result()
        except _cf.TimeoutError:
            raise RuntimeError("la descarga del Drive tardó demasiado (>8 min). "
                               "Reintentá, o probá con menos videos / archivos más chicos.")
    return [p for p in out if p]


def _ads_run(job, params):
    """Baja de Drive → sube videos → crea campaña + N conjuntos + ads. Con progreso."""
    _ads_local.token = params.get("_token") or None   # usar el token del usuario que lanzó (cuenta correcta)
    st = _ADS_JOBS.get(job)
    import tempfile, shutil
    tmp = tempfile.mkdtemp(prefix="ads_")
    try:
        cfg = dict(_ADS_CUENTAS.get(params.get("cuenta") or "cp1") or _ADS_CUENTAS["cp1"])
        if (params.get("page") or "").strip():
            cfg["page"] = params["page"].strip()
        if (params.get("pixel") or "").strip():
            cfg["pixel"] = params["pixel"].strip()
        if "ig" in params:
            cfg["ig"] = (params.get("ig") or "").strip()
        acct, pixel = cfg["ad_account"], cfg["pixel"]
        cbo = (params.get("tipo") or "cbo") != "abo"
        budget_sharing = bool(params.get("budget_sharing"))   # solo aplica en ABO (compartir 20%)
        presup = int(params.get("presupuesto") or cfg["presupuesto"])
        n_conj = max(1, min(20, int(params.get("conjuntos") or 1)))
        # Por defecto ACTIVA+programada: solo queda en PAUSA si el usuario elige explícitamente "pausada".
        # (Antes, cualquier cosa que no fuera exactamente "activa" salía en pausa → los ads salían apagados.)
        estado = "PAUSED" if params.get("estado") == "pausada" else "ACTIVE"
        angulo = (params.get("angulo") or "VARIOS").strip()
        ad = {"copy": (params.get("copy") or "").strip(), "titulo": (params.get("titulo") or "").strip(),
              "subtitulo": (params.get("subtitulo") or "").strip(), "url": (params.get("url") or "").strip()}
        modo_conj = params.get("modo_conjunto") or "nuevo"   # nuevo | dup | usar
        src = params.get("adset_src_id")
        start = _ads_sched(params)                            # día/hora de salida

        up_id = (params.get("upload_id") or "").strip()
        if up_id:
            st["msg"] = "Tomando tus videos…"
            updir = _ADS_UPLOADS.get(up_id)
            rutas = sorted(_os.path.join(updir, f) for f in _os.listdir(updir)) if (updir and _os.path.isdir(updir)) else []
            if not rutas:
                raise RuntimeError("no encontré los videos que subiste (probá subirlos de nuevo)")
        else:
            st["msg"] = "Bajando videos de Drive…"
            rutas = _ads_drive_bajar(params.get("drive", ""), tmp,
                                     on_prog=lambda k, t: st.update({"msg": "Bajando videos… %d/%d" % (k, t)}))
            if not rutas:
                raise RuntimeError("no encontré videos en ese Drive (¿está compartido con la service account?)")
        n = len(rutas)
        _adsets_prev = 1 if (modo_conj == "usar" and src) else n_conj
        # barra completa desde el arranque = subir videos (n) + crear anuncios (n × conjuntos). Solo avanza.
        st["total"] = n + n * _adsets_prev; st["done"] = 0

        # subir videos EN PARALELO. NO esperamos el procesado completo de Meta (eso tardaba minutos):
        # Meta acepta crear el anuncio con el video procesándose, y si no está listo reintentamos abajo.
        import concurrent.futures as _cf
        medios = [None] * n
        _pl = threading.Lock(); _pn = {"n": 0}
        _tok_prep = getattr(_ads_local, "token", None)     # token de la cuenta correcta, para los threads

        def _prep(idx, ruta):
            _ads_local.token = _tok_prep                   # propagar el token a este thread (subir video a la cuenta correcta)
            if _ads_es_imagen(ruta):
                medio = {"kind": "image", "image_hash": _ads_subir_imagen(acct, ruta)}
            else:
                vid = _ads_subir_video(acct, ruta)
                # la miniatura se saca al CREAR el anuncio (no acá) para no frenar la subida
                medio = {"kind": "video", "video_id": vid, "thumb": None}
            with _pl:
                _pn["n"] += 1
                st["done"] = _pn["n"]
                st["msg"] = "Subiendo videos %d/%d…" % (_pn["n"], n)
            return idx, medio

        # OJO memoria: cada upload a Meta buffea el video entero en RAM. Con el plan de 512MB,
        # 6 en paralelo revientan (OOM → Render reinicia → 502). Max 2 a la vez = ~120MB, entra.
        with _cf.ThreadPoolExecutor(max_workers=min(2, max(1, n))) as _ex:
            _futs = [_ex.submit(_prep, i, r) for i, r in enumerate(rutas)]
            for _f in _cf.as_completed(_futs):
                _idx, _m = _f.result()
                medios[_idx] = _m

        # campaña
        st["msg"] = "Creando campaña…"
        now = _dt.datetime.utcnow() - _dt.timedelta(hours=3)
        # La fecha del NOMBRE = el día REAL en que arranca (sale de `start`, que ya se corrigió a
        # futuro en _ads_sched). Así el nombre nunca dice un día vencido.
        try:
            _fd = _dt.date.fromisoformat(start[:10])
        except Exception:
            _fd = now.date() if now.hour < 5 else (now + _dt.timedelta(days=1)).date()
        fecha = "%d-%d" % (_fd.day, _fd.month)
        if params.get("modo_campana") == "existente" and params.get("campaign_id"):
            campaign_id = params["campaign_id"]
        else:
            campaign_id = _ads_crear(acct, "campaigns",
                                     _ads_camp_payload("%s %s" % (fecha, angulo), cbo, presup, estado, budget_sharing))

        # determinar los CONJUNTOS destino
        base = (params.get("conjunto_nombre") or "CONJUNTO").strip() or "CONJUNTO"
        adsets = []
        if modo_conj == "usar" and src:
            adsets = [src]                                   # añadir los ads a un conjunto existente
            n_conj = 1
        else:
            for c in range(n_conj):
                st["msg"] = "Creando conjunto %d de %d…" % (c + 1, n_conj)
                nombre_conj = base if n_conj == 1 else ("%s %d" % (base, c + 1))
                if modo_conj == "dup" and src:              # copia la config de un conjunto existente
                    adsets.append(_ads_adset_dup(acct, src, campaign_id, nombre_conj, pixel, estado, start,
                                                 presup_override=params.get("presup_conjunto")))
                elif params.get("modo_campana") == "existente":
                    # conjunto NUEVO (sin copiar) dentro de una campaña existente:
                    # respetá el tipo REAL de esa campaña (ABO → presupuesto en el conjunto; CBO → sin presupuesto).
                    _abo = not bool(params.get("camp_cbo"))
                    try:
                        _pcj = int(float(params.get("presup_conjunto"))) if str(params.get("presup_conjunto") or "").strip() else presup
                    except Exception:
                        _pcj = presup
                    adsets.append(_ads_crear(acct, "adsets",
                                             _ads_adset_payload(nombre_conj, campaign_id, pixel, (not _abo), _pcj, estado, start)))
                else:                                        # conjunto nuevo estándar (campaña nueva)
                    adsets.append(_ads_crear(acct, "adsets",
                                             _ads_adset_payload(nombre_conj, campaign_id, pixel, cbo, presup, estado, start)))

        # 2ª parte de la barra = crear los anuncios (la fase más lenta).
        import time as _t
        total_ads = len(adsets) * len(medios)

        # ads EN PARALELO (1 por video). La miniatura se saca acá y se reintenta si el video
        # TODAVÍA se procesa en Meta (no esperamos el procesado completo antes, para que sea rápido).
        _tok_ad = getattr(_ads_local, "token", None)      # token de la cuenta correcta, para los threads
        if params.get("repartir") and len(adsets) > 1:
            # REPARTIR: cada video va a UN conjunto. Si viene reparto_map (la elección por video del
            # usuario, cuántos en cada conjunto), lo respeta; si no, reparte por orden en bloques parejos.
            rmap = params.get("reparto_map") or []
            import math as _math_rep
            _per = max(1, _math_rep.ceil(len(medios) / len(adsets)))
            tareas = []
            _cont = {}
            for _vi, m in enumerate(medios):
                try:
                    _c = int(rmap[_vi]) if (_vi < len(rmap) and rmap[_vi]) else (_vi // _per + 1)
                except Exception:
                    _c = _vi // _per + 1
                _c = max(1, min(len(adsets), _c))          # clamp al rango de conjuntos
                _cont[_c] = _cont.get(_c, 0) + 1
                tareas.append((adsets[_c - 1], _cont[_c], m))
        else:
            tareas = [(a, i, m) for a in adsets for i, m in enumerate(medios, start=1)]
        total_ads = len(tareas)   # total REAL (con repartir = nº de videos, no videos×conjuntos)

        def _crear_ad(adset_id, i, medio):
            _ads_local.token = _tok_ad                    # propagar el token a este thread (no cruzar cuentas)
            _ultimo = None
            for _intento in range(6):
                try:
                    if medio.get("kind") == "video" and not medio.get("thumb"):
                        medio["thumb"] = _ads_thumb(medio["video_id"])   # miniatura requerida
                    cid = _ads_crear(acct, "adcreatives", _ads_creative_payload(str(i), medio, cfg, ad))
                    _ads_crear(acct, "ads", {"name": str(i), "adset_id": adset_id,
                                             "creative": {"creative_id": cid}, "status": estado})
                    with _pl:
                        _pn["n"] += 1
                        st["done"] = _pn["n"]
                        st["msg"] = "Creando anuncios… %d/%d" % (_pn["n"] - n, total_ads)
                    return
                except Exception as _ex:
                    _ultimo = _ex
                    _m = str(_ex).lower()
                    # errores de video-aún-procesándose → esperá un toque y reintentá
                    if any(k in _m for k in ("proces", "process", "not ready", "todav", "still",
                                             "transcod", "prepar", "no está list", "no esta list")):
                        _t.sleep(5 * (_intento + 1))
                        continue
                    raise
            raise _ultimo

        with _cf.ThreadPoolExecutor(max_workers=min(6, max(1, len(tareas)))) as _ex2:
            _fs = [_ex2.submit(_crear_ad, a, i, m) for (a, i, m) in tareas]
            for _f in _cf.as_completed(_fs):
                _f.result()                               # propaga la excepción si alguno falló
        creados = len(tareas)
        # ENCENDER LOS ADS: Meta a veces crea los ads PAUSED/WITH_ISSUES porque el video TODAVÍA se
        # procesaba (no esperamos el procesado antes, para que la subida sea rápida). Pasada final:
        # re-activa SOLO los que quedaron pausados/con-issues, cuando el procesado ya terminó. Así
        # salen ENCENDIDOS (programados) y no apagados. (El worker de gunicorn ya no tiene timeout.)
        needs_appr = False
        if estado == "ACTIVE":
            st["msg"] = "Encendiendo anuncios…"

            def _es_aprob(a):
                for it in (a.get("issues_info") or []):
                    t = ((it.get("error_summary") or "") + " " + (it.get("error_message") or "")).lower()
                    if "aprob" in t or "usuarios de confianza" in t or "circulaci" in t:
                        return True
                return False

            _fails = 0
            for _r in range(6):
                _t.sleep(10)
                try:
                    _q = _ads_call("GET", campaign_id,
                                   params={"fields": "ads.limit(80){id,status,effective_status,issues_info}"})
                    _lst = (_q.get("ads") or {}).get("data", [])
                    _fails = 0
                except Exception:
                    _fails += 1
                    if _fails >= 2:            # Meta nos limita (rate limit): NO colgamos el job, salimos
                        break
                    continue
                _pend = [a for a in _lst
                         if a.get("status") != "ACTIVE" or a.get("effective_status") == "WITH_ISSUES"]
                # Meta pide aprobación de admin (publicar por API/System User): la API NO lo destraba,
                # lo tiene que aprobar un humano. No reintentamos al pepe: avisamos y salimos.
                if any(_es_aprob(a) for a in _pend):
                    needs_appr = True
                    break
                if _lst and not _pend:
                    break
                for a in _pend:                                  # re-encender los que Meta pausó (video procesándose)
                    try:
                        _ads_call("POST", a["id"], data={"status": "ACTIVE"})
                    except Exception:
                        pass
        st["done"] = st["total"]
        _est_txt = ("⚠ APROBÁ los anuncios en Meta (te pidió aprobación de admin — revisá tu email/notificaciones)"
                    if needs_appr else ("Programada 5 AM" if estado == "ACTIVE" else "Pausada"))
        st["stats"] = {"campaign_id": campaign_id, "conjuntos": len(adsets), "ads": creados,
                       "tipo": "CBO" if cbo else "ABO", "estado": _est_txt, "needs_approval": needs_appr}
        st["msg"] = "¡Listo! %d anuncios en %d conjunto(s). %s" % (creados, n_conj, _est_txt)
        st["listo"] = True
    except Exception as e:
        st["error"] = str(e); st["listo"] = True
    finally:
        try:
            shutil.rmtree(tmp, ignore_errors=True)
        except Exception:
            pass


