# ================= WhatsApp (Cloud API) — módulo AISLADO =================
# No toca el dashboard. Storage propio en el disco persistente (/var/data). La vinculación es
# por NÚMERO de API (phone_id + token + waba_id). El webhook lo sirve RealProfit (HTTPS de Render,
# siempre arriba) y REENVÍA lo entrante al bot de METAFY (forward_url) para no cortar el auto-respondedor.
WA_TOKENS = DATA_DIR / "wa_tokens.json"   # {email: {phone_id, token, waba_id, verify_token, forward_url, numero}}
WA_CHATS = DATA_DIR / "wa_chats.json"     # {email: {wa_id: {name, updated, messages:[...]}}}
WA_GRAPH = "https://graph.facebook.com/v21.0"
# Servicio WhatsApp Web (Baileys), corre aparte en Render. RealProfit le habla por HTTP.
WA_WEB_URL = _os.environ.get("WA_WEB_URL", "").rstrip("/")     # ej https://realprofit-wa-web.onrender.com
WA_WEB_SECRET = _os.environ.get("WA_WEB_SECRET", "")           # mismo secret que el servicio Node
_WA_WEB_NAMES = {}   # email -> nombre del número conectado por Web (ej "NoxaLab Argentina") para la marca del bot


def _wa_marca_auto(email, cfg):
    """Marca del bot: la cargada por el dueño, o si no, el nombre del número de WhatsApp conectado
    (así el bot responde como el negocio de la cuenta, nunca hardcodeado)."""
    m = (cfg.get("bot_marca") or "").strip() if isinstance(cfg, dict) else ""
    return m or (_WA_WEB_NAMES.get(email) or "").strip()


def _wa_web_keepalive():
    """Ping al servicio de WhatsApp Web cada 5 min para que Render no lo duerma (mientras RealProfit esté vivo)."""
    import time as _t
    while True:
        try:
            if WA_WEB_URL:
                requests.get(WA_WEB_URL + "/health", timeout=15)
        except Exception:
            pass
        _t.sleep(180)


if WA_WEB_URL:
    try:
        threading.Thread(target=_wa_web_keepalive, daemon=True).start()
    except Exception:
        pass

try:    # bot de finanzas: completa la planilla del día vencido ~1:15am (hora AR)
    threading.Thread(target=_fin_bot_loop, daemon=True, name="fin-bot").start()
except Exception:
    pass


def _wa_web_send(email, wid, text):
    """Manda un texto por el WhatsApp Web (servicio Baileys). Devuelve (ok, id, err)."""
    if not (WA_WEB_URL and WA_WEB_SECRET):
        return False, "", "servicio Web no configurado"
    try:
        r = requests.post(WA_WEB_URL + "/send",
                          headers={"x-wa-secret": WA_WEB_SECRET},
                          json={"acc": email, "to": wid, "text": text}, timeout=20)
        j = r.json() if r.content else {}
        if r.status_code >= 400 or not j.get("ok"):
            return False, "", j.get("msg", "error %s" % r.status_code)
        return True, "", ""
    except Exception as e:
        return False, "", str(e)[:120]


