# ══════════════ Transferencias + Carritos — envío WhatsApp desde RealProfit ══════════════
# Fuente ÚNICA de verdad del envío (consolidado acá). El dedupe lee el log de chats de RealProfit
# (_wa_chats_all), sembrado con lo que ya mandó la Mac. NUNCA duplicar (ver incidente 22-ago).
WA_TPL_TRANSF = "datos_transferencia"      # params: nombre, pedido, cbu, titular, monto
WA_TPL_CARRITO = "carrito_abandonado"      # params: nombre, url
WA_CARRITO_DISCOUNT = "CARRITO10"          # cupón 10% que se AUTO-APLICA en el link de Shopify (&discount=)

# ── Acortador de links (para que el mensaje del carrito NO salga con "Ver más") ──
CARR_LINKS_FILE = DATA_DIR / "carrito_links.json"   # {codigo: url_completa}  (persistente → los links viejos siguen andando)
CARR_SHORT_BASE = "https://www.realprofitapp.com/c/"
_CARR_LINKS = None
_CARR_LINKS_LOCK = threading.Lock()


def _carr_links():
    global _CARR_LINKS
    if _CARR_LINKS is None:
        try:
            _CARR_LINKS = _json.loads(CARR_LINKS_FILE.read_text(encoding="utf-8"))
        except Exception:
            _CARR_LINKS = {}
    return _CARR_LINKS


def _carr_short(url):
    """URL CORTA (realprofitapp.com/c/xxxxx) para `url`. Código ESTABLE (mismo carrito → mismo código).
    Actualiza en MEMORIA; el archivo se persiste una sola vez con _carr_links_save()."""
    import hashlib
    code = hashlib.sha1(url.encode("utf-8")).hexdigest()[:7]
    _carr_links()[code] = url
    return CARR_SHORT_BASE + code


def _carr_links_save():
    with _CARR_LINKS_LOCK:
        try:
            CARR_LINKS_FILE.write_text(_json.dumps(_carr_links()), encoding="utf-8")
        except Exception:
            pass


@app.get("/c/<code>")
def carr_redirect(code):
    """Redirige el link corto del carrito al recover real de Shopify (con el descuento). PÚBLICO."""
    url = _carr_links().get(code)
    if not url:
        return "Link no encontrado", 404
    return redirect(url, code=302)


WA_TPL_LANG = "es_AR"
WA_CBU_DEFAULT = "0070059730004102336598"
WA_TITULAR_DEFAULT = "Cristian Acosta"


def _wa_e164(t):
    d = re.sub(r"\D", "", t or ""); d = d.lstrip("0")
    if d.startswith("15"): d = d[2:]
    if not d.startswith("54"): d = "54" + d
    if d.startswith("54") and not d.startswith("549"): d = "549" + d[2:]
    return d


def _wa_marca_enviados(email, tipo):
    """Set de teléfonos (E164) que YA recibieron ese tipo ('carrito'|'transfer'), del log de chats."""
    chats = _wa_chats_all().get(email, {})
    if tipo == "carrito":
        # detecta el formato viejo ([carrito ...) Y el mensaje lindo nuevo (por el texto y el link de recuperación)
        marcas = ("[carrito", "regalo10", "carrito10", "no la finalizaste",
                  "en tu carrito", "/checkouts/ac", "abandoned_checkout")
    else:
        marcas = ("[transfer", "cbu ", "transfer")
    ya = set()
    for wid, conv in chats.items():
        for m in conv.get("messages", []):
            if m.get("dir") != "out":
                continue
            t = (m.get("text") or "").lower()
            if any(s in t for s in marcas):
                ya.add(_wa_e164(wid)); break
    return ya


def _wa_send_tpl(email, conf, wid, tpl_name, params, log_text):
    """Manda una plantilla y la loguea en el chat de RealProfit. Devuelve (ok, detalle)."""
    tpl = {"name": tpl_name, "language": {"code": WA_TPL_LANG}}
    if params:
        tpl["components"] = [{"type": "body", "parameters": [{"type": "text", "text": p} for p in params]}]
    try:
        r = requests.post("%s/%s/messages" % (WA_GRAPH, conf["phone_id"]),
                          headers={"Authorization": "Bearer " + conf["token"]},
                          json={"messaging_product": "whatsapp", "to": wid, "type": "template", "template": tpl},
                          timeout=20)
        j = r.json()
    except Exception as e:
        return False, str(e)[:120]
    if r.status_code >= 400:
        return False, str((j.get("error") or {}).get("message", "error"))[:160]
    mid = (j.get("messages") or [{}])[0].get("id", "")
    try:
        with _WA_LOG_LOCK:                       # write serializada → seguro con envíos concurrentes
            chats = _wa_chats_all()
            conv = chats.setdefault(email, {}).setdefault(wid, {"name": wid, "messages": []})
            conv["messages"].append({"dir": "out", "text": log_text, "ts": _wa_now(),
                                     "type": "template", "id": mid, "status": "sent"})
            conv["updated"] = _wa_now()
            _wa_save_chats(chats)
    except Exception:
        pass
    return True, "ok"


def _wa_transfers_list(email):
    """Pedidos TN pendientes de pago (candidatos a mandar CBU). Marca los ya enviados."""
    tk = _tn_tokens().get(email) or {}
    if not (tk.get("access_token") and tk.get("store_id")):
        return []
    store, hdr = tk["store_id"], _tn_headers(tk["access_token"])
    ya = _wa_marca_enviados(email, "transfer")
    out = []
    for page in (1, 2):
        try:
            r = requests.get("%s/%s/orders" % (TN_API, store), headers=hdr, params={
                "per_page": 50, "page": page, "payment_status": "pending", "status": "open", "sort": "-id",
                "fields": "number,contact_name,shipping_address,total,contact_phone,billing_phone,created_at"}, timeout=30)
            d = r.json() if r.content else []
        except Exception:
            d = []
        if not isinstance(d, list) or not d:
            break
        for o in d:
            sa = _D(o.get("shipping_address"))
            tel = sa.get("phone") or o.get("contact_phone") or o.get("billing_phone") or ""
            if not re.sub(r"\D", "", tel or ""):
                continue
            k = _wa_e164(tel)
            out.append({"num": str(o.get("number")), "nombre": sa.get("name") or o.get("contact_name") or "—",
                        "total": o.get("total"), "tel": k, "fecha": (o.get("created_at") or "")[:10],
                        "enviado": k in ya})
        if len(d) < 50:
            break
    return out


def _shop_paginate(url, headers, params, key, cap=20):
    """GET paginado de Shopify por Link header. Reintenta 429/5xx. Devuelve la lista de `key`."""
    import time as _tsleep
    out = []
    for _ in range(cap):
        try:
            r = requests.get(url, headers=headers, params=params, timeout=30)
        except Exception:
            break
        if r.status_code == 429 or r.status_code >= 500:
            _tsleep.sleep(float(r.headers.get("Retry-After", 1)) + 0.3); continue
        if r.status_code != 200:
            break
        out.extend((r.json() or {}).get(key, []))
        link = r.headers.get("Link", "") or r.headers.get("link", "")
        nxt = None
        for part in link.split(","):
            if 'rel="next"' in part and "<" in part and ">" in part:
                nxt = part[part.find("<") + 1:part.find(">")]
        if not nxt:
            break
        url = nxt; params = None
    return out


def _shopify_abandoned(shop, token, dias):
    """Carritos abandonados de Shopify (checkouts NO completados) de los últimos `dias`."""
    since = (_dt.date.today() - _dt.timedelta(days=dias + 1)).isoformat()
    return _shop_paginate("https://%s/admin/api/2026-07/checkouts.json" % shop,
                          {"X-Shopify-Access-Token": token},
                          {"limit": 250, "status": "open", "created_at_min": since + "T00:00:00-03:00"},
                          "checkouts")


def _shopify_buyers(shop, token, dias=25):
    """Teléfonos (E164) y emails de compradores Shopify recientes → para EXCLUIR del carrito."""
    tels, mails = set(), set()
    since = (_dt.date.today() - _dt.timedelta(days=dias)).isoformat()
    ords = _shop_paginate("https://%s/admin/api/2026-07/orders.json" % shop,
                          {"X-Shopify-Access-Token": token},
                          {"status": "any", "limit": 250, "created_at_min": since + "T00:00:00-03:00",
                           "fields": "phone,email,customer,shipping_address,billing_address"},
                          "orders")
    for o in ords:
        ph = (o.get("phone") or (o.get("customer") or {}).get("phone")
              or (_D(o.get("shipping_address"))).get("phone")
              or (_D(o.get("billing_address"))).get("phone"))
        if ph:
            tels.add(_wa_e164(ph))
        em = (o.get("email") or (o.get("customer") or {}).get("email") or "").lower()
        if em:
            mails.add(em)
    return tels, mails


def _wa_carritos_list(email, dias=14):
    """Carritos abandonados NO contactados (TiendaNube + Shopify) con filtro seguro:
    excluye ya-contactados, compradores y dedupe por teléfono (1 por tel). Cada item trae `tienda`."""
    ya = _wa_marca_enviados(email, "carrito")
    compr_t, compr_m = set(), set()
    now = _dt.datetime.now(_dt.timezone.utc)
    cand = {}
    # ───────────── TiendaNube ─────────────
    tk = _tn_tokens().get(email) or {}
    if tk.get("access_token") and tk.get("store_id"):
        store, hdr = tk["store_id"], _tn_headers(tk["access_token"])
        for page in (1, 2, 3):
            try:
                r = requests.get("%s/%s/orders" % (TN_API, store), headers=hdr, params={
                    "per_page": 200, "page": page, "fields": "contact_phone,contact_email",
                    "created_at_min": (_dt.date.today() - _dt.timedelta(days=25)).isoformat()}, timeout=30)
                d = r.json() if r.content else []
            except Exception:
                d = []
            if not isinstance(d, list) or not d:
                break
            for o in d:
                if o.get("contact_phone"):
                    compr_t.add(_wa_e164(o["contact_phone"]))
                if o.get("contact_email"):
                    compr_m.add((o["contact_email"] or "").lower())
            if len(d) < 200:
                break
        parar = False
        for page in range(1, 15):
            if parar:
                break
            try:
                r = requests.get("%s/%s/checkouts" % (TN_API, store), headers=hdr,
                                 params={"per_page": 100, "page": page}, timeout=30)
                d = r.json() if r.content else []
            except Exception:
                d = []
            if not isinstance(d, list) or not d:
                break
            for o in d:
                try:
                    cr = _dt.datetime.fromisoformat(o["created_at"].replace("Z", "+00:00"))
                except Exception:
                    continue
                if (now - cr).days > dias:
                    parar = True; continue
                if o.get("completed_at"):
                    continue
                tel = o.get("contact_phone") or o.get("shipping_phone")
                if not tel or not re.sub(r"\D", "", tel):
                    continue
                if not o.get("abandoned_checkout_url"):
                    continue
                k = _wa_e164(tel)
                mail = (o.get("contact_email") or "").lower()
                if k in ya or k in compr_t or (mail and mail in compr_m):   # ya enviado o ya compró → FUERA
                    continue
                if k not in cand or cr > cand[k]["cr"]:
                    cand[k] = {"cr": cr, "nombre": o.get("contact_name") or o.get("shipping_name") or "cliente",
                               "url": _carr_short(o.get("abandoned_checkout_url")), "total": o.get("total"),
                               "dias": (now - cr).days, "tienda": "tn"}
            if len(d) < 100:
                break
    # ───────────── Shopify ─────────────
    tks = _shop_tokens().get(email) or {}
    if tks.get("access_token") and tks.get("shop"):
        shop, token = tks["shop"], tks["access_token"]
        abandonados = []
        _got = _SHOP_SEM.acquire(timeout=4)   # tope de ops pesadas → NUNCA cuelga todos los hilos del server
        if _got:
            try:
                try:
                    st, sm = _shopify_buyers(shop, token, dias)
                    compr_t |= st; compr_m |= sm
                except Exception:
                    pass
                try:
                    abandonados = _shopify_abandoned(shop, token, dias)
                except Exception:
                    abandonados = []
            finally:
                _SHOP_SEM.release()
        for co in abandonados:
            if co.get("completed_at"):
                continue
            try:
                cr = _dt.datetime.fromisoformat((co.get("created_at") or "").replace("Z", "+00:00"))
            except Exception:
                continue
            if (now - cr).days > dias:
                continue
            cust = co.get("customer") or {}
            tel = (co.get("phone") or cust.get("phone")
                   or (_D(co.get("shipping_address"))).get("phone")
                   or (_D(co.get("billing_address"))).get("phone"))
            if not tel or not re.sub(r"\D", "", tel):
                continue
            url = co.get("abandoned_checkout_url")
            if not url:
                continue
            url += ("&" if "?" in url else "?") + "discount=" + WA_CARRITO_DISCOUNT   # auto-aplica el cupón
            url = _carr_short(url)   # link CORTO → el mensaje no sale con "Ver más"
            k = _wa_e164(tel)
            mail = (co.get("email") or cust.get("email") or "").lower()
            if k in ya or k in compr_t or (mail and mail in compr_m):   # ya enviado o ya compró → FUERA
                continue
            nombre = (cust.get("first_name")
                      or (_D(co.get("shipping_address"))).get("first_name")
                      or (_D(co.get("shipping_address"))).get("name") or "cliente")
            if k not in cand or cr > cand[k]["cr"]:
                cand[k] = {"cr": cr, "nombre": nombre, "url": url,
                           "total": co.get("total_price"), "dias": (now - cr).days, "tienda": "shopify"}
    items = [{"tel": k, "nombre": v["nombre"], "url": v["url"], "total": v["total"],
              "dias": v["dias"], "tienda": v.get("tienda", "")}
             for k, v in cand.items()]
    items.sort(key=lambda it: it["dias"])   # solo PENDIENTES (no enviados) · más nuevos arriba
    _carr_links_save()                       # persisto los links cortos generados (una sola vez)
    return items


@app.get("/wa-transfers")
def wa_transfers():
    email = _user_actual()
    if not email:
        return jsonify({"ok": False}), 401
    conf = _wa_conf(email) or {}
    return jsonify({"ok": True, "wpp_on": bool(conf.get("token") and conf.get("phone_id")),
                    "cbu": conf.get("cbu") or WA_CBU_DEFAULT, "titular": conf.get("titular") or WA_TITULAR_DEFAULT,
                    "items": _wa_transfers_list(email)})


@app.post("/wa-transfers-enviar")
def wa_transfers_enviar():
    email = _user_actual()
    if not email:
        return jsonify({"ok": False}), 401
    conf = _wa_conf(email)
    if not (conf and conf.get("token") and conf.get("phone_id")):
        return jsonify({"ok": False, "msg": "WhatsApp no conectado"})
    data = request.get_json(silent=True) or {}
    solo = set(data.get("tels") or [])            # si viene, manda solo esos; si no, todos los pendientes
    cbu = (data.get("cbu") or conf.get("cbu") or WA_CBU_DEFAULT).strip()
    titular = (data.get("titular") or conf.get("titular") or WA_TITULAR_DEFAULT).strip()
    ya = _wa_marca_enviados(email, "transfer")     # re-chequeo anti-duplicado en el momento del envío
    env = salt = fail = 0
    errores = []
    for it in _wa_transfers_list(email):
        k = it["tel"]
        if solo and k not in solo:
            continue
        if k in ya or it.get("enviado"):
            salt += 1
            continue
        n = (it["nombre"] or "cliente").split()[0]
        monto = str(int(round(float(it.get("total") or 0))))
        ok, det = _wa_send_tpl(email, conf, k, WA_TPL_TRANSF, [n, it["num"], cbu, titular, monto],
                               "[transfer] #%s CBU %s a %s por %s" % (it["num"], cbu, titular, monto))
        if ok:
            env += 1; ya.add(k)
        else:
            fail += 1; errores.append({"num": it["num"], "msg": det})
    return jsonify({"ok": True, "enviados": env, "saltados": salt, "fallaron": fail, "errores": errores[:5]})


@app.get("/wa-carritos")
def wa_carritos():
    email = _user_actual()
    if not email:
        return jsonify({"ok": False}), 401
    conf = _wa_conf(email) or {}
    try:
        dias = max(1, min(30, int(request.args.get("dias") or 14)))
    except Exception:
        dias = 14
    import time as _t
    refresh = request.args.get("refresh") in ("1", "true", "yes")
    _c = _CARR_CACHE.get(email)
    if (not refresh) and _c and _c.get("dias") == dias and (_t.time() - _c.get("ts", 0) < _CARR_TTL):
        items = _c["items"]                                  # caché fresco → no rebaja Shopify de nuevo
    else:
        try:
            items = _wa_carritos_list(email, dias)
        except Exception as e:
            import traceback
            tb = traceback.extract_tb(e.__traceback__)[-1]
            det = "%s: %s @ %s:%d" % (type(e).__name__, str(e)[:200], tb.name, tb.lineno)
            return jsonify({"ok": False, "err": det})
        _CARR_CACHE[email] = {"dias": dias, "ts": _t.time(), "items": items}
    nsh = sum(1 for x in items if x.get("tienda") == "shopify")
    ntn = sum(1 for x in items if x.get("tienda") == "tn")
    n_pend = sum(1 for x in items if not x.get("enviado"))
    n_env = sum(1 for x in items if x.get("enviado"))
    return jsonify({"ok": True, "wpp_on": bool(conf.get("token") and conf.get("phone_id")),
                    "dias": dias, "cupon": WA_CARRITO_DISCOUNT, "n_tn": ntn, "n_shopify": nsh,
                    "n_pend": n_pend, "n_env": n_env, "items": items})


@app.post("/wa-carritos-enviar")
def wa_carritos_enviar():
    email = _user_actual()
    if not email:
        return jsonify({"ok": False}), 401
    conf = _wa_conf(email)
    if not (conf and conf.get("token") and conf.get("phone_id")):
        return jsonify({"ok": False, "msg": "WhatsApp no conectado"})
    data = request.get_json(silent=True) or {}
    solo = set(data.get("tels") or [])
    try:
        dias = max(1, min(30, int(data.get("dias") or 14)))
    except Exception:
        dias = 14
    # NO invalido el caché acá (el front manda en lotes; si lo invalidara, cada lote rebajaría Shopify de nuevo).
    ya = _wa_marca_enviados(email, "carrito")      # re-chequeo anti-duplicado al momento de mandar
    salt = 0
    pendientes = []
    for it in _wa_carritos_list(email, dias):
        k = it["tel"]
        if solo and k not in solo:
            continue
        if k in ya:
            salt += 1
            continue
        pendientes.append(it)

    def _envia_carrito(it):
        n = (it["nombre"] or "cliente").split()[0]
        # Se loguea el MENSAJE REAL (tal como lo recibe el cliente), no el texto interno feo.
        msg_log = ("¡Hola %s! \U0001F44B\n\nVimos que dejaste productos en tu carrito y no llegaste a "
                   "terminar la compra. Te lo guardamos \U0001F6D2\n\nEntrá acá y ya te aplicamos el "
                   "10%% OFF automático \U0001F447\n%s") % (n, it["url"])
        ok, det = _wa_send_tpl(email, conf, it["tel"], WA_TPL_CARRITO, [n, it["url"]], msg_log)
        return (it["tel"], ok, det)

    env = fail = 0
    errores = []
    if pendientes:
        from concurrent.futures import ThreadPoolExecutor
        # La Cloud API NO banea por volumen → mando en PARALELO (8 a la vez) = mucho más rápido.
        with ThreadPoolExecutor(max_workers=8) as _ex:
            for k, ok, det in _ex.map(_envia_carrito, pendientes):
                if ok:
                    env += 1
                else:
                    fail += 1; errores.append({"tel": k, "msg": det})
    _CARR_CACHE.pop(email, None)                    # al terminar, invalido el caché (cambió el estado Enviado)
    return jsonify({"ok": True, "enviados": env, "saltados": salt, "fallaron": fail, "errores": errores[:5]})


@app.post("/wa-seed-enviados")
def wa_seed_enviados():
    """Siembra el dedupe con teléfonos ya contactados desde otra máquina (la Mac). tipo=carrito|transfer."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False}), 401
    data = request.get_json(silent=True) or {}
    tipo = (data.get("tipo") or "carrito").strip()
    tels = data.get("tels") or []
    marca = "[carrito] (sembrado)" if tipo == "carrito" else "[transfer] (sembrado)"
    chats = _wa_chats_all()
    n = 0
    for t in tels:
        k = _wa_e164(t)
        if not k:
            continue
        conv = chats.setdefault(email, {}).setdefault(k, {"name": k, "messages": []})
        conv["messages"].append({"dir": "out", "text": marca, "ts": _wa_now(), "type": "seed", "status": "sent"})
        conv["updated"] = _wa_now()
        n += 1
