@app.post("/wa-bot-config")
def wa_bot_config_set():
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesión"})
    toks = _wa_tokens()
    c = toks.get(email)
    if not c:
        return jsonify({"ok": False, "msg": "WhatsApp no conectado"})
    if "bot" in request.form:
        c["bot"] = request.form.get("bot") in ("1", "true", "on", "True")
    if "mode" in request.form:
        c["bot_mode"] = "draft" if request.form.get("mode") == "draft" else "auto"
    if "instr" in request.form:
        c["bot_instr"] = (request.form.get("instr") or "")[:6000]
    if "marca" in request.form:
        c["bot_marca"] = (request.form.get("marca") or "")[:80]
    if "pago_titular" in request.form:
        c["bot_pago_titular"] = (request.form.get("pago_titular") or "")[:120]
    if "pago_alias" in request.form:
        c["bot_pago_alias"] = (request.form.get("pago_alias") or "")[:120]
    if "pago_cuit" in request.form:
        c["bot_pago_cuit"] = (request.form.get("pago_cuit") or "")[:20]
    if "canal" in request.form:
        v = request.form.get("canal")
        c["bot_canal"] = v if v in ("api", "web", "ambos") else "api"
    if "sched" in request.form:
        c["bot_sched"] = "franja" if request.form.get("sched") == "franja" else "24h"
    def _hhmm(s, dflt):
        import re as _re
        s = (s or "").strip()
        return s if _re.match(r"^\d{1,2}:\d{2}$", s) else dflt
    if "desde" in request.form:
        c["bot_desde"] = _hhmm(request.form.get("desde"), "20:00")
    if "hasta" in request.form:
        c["bot_hasta"] = _hhmm(request.form.get("hasta"), "09:00")
    _wa_save_tokens(toks)
    return jsonify({"ok": True, "bot": bool(c.get("bot")), "mode": c.get("bot_mode", "auto"),
                    "canal": c.get("bot_canal", "api"), "activo_ahora": _bot_activo_ahora(c)})


@app.post("/wa-bot-probar")
def wa_bot_probar():
    """Probador: le tirás un mensaje de cliente y devuelve qué DECIDIRÍA el bot, sin enviar nada."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesión"})
    c = _wa_conf(email) or {}
    txt = (request.form.get("text") or "").strip()
    nombre = (request.form.get("nombre") or "").strip()
    if not txt:
        return jsonify({"ok": False, "msg": "escribí un mensaje de prueba"})
    try:
        import agente_ia
    except Exception as e:
        return jsonify({"ok": False, "msg": "cerebro no disponible: " + str(e)[:80]})
    if not agente_ia.disponible():
        return jsonify({"ok": False, "msg": "Falta ANTHROPIC_API_KEY en el servidor (Render → Environment)"})
    hist = [{"dir": "in", "texto": txt}]
    d = agente_ia.decidir(hist, nombre=nombre, extra_instr=_bot_extra_instr(c),
                          marca=_wa_marca_auto(email, c),
                          pago={"titular": c.get("bot_pago_titular", ""),
                                "alias": c.get("bot_pago_alias", ""),
                                "cuit": c.get("bot_pago_cuit", "")})
    return jsonify({"ok": True, "d": d})


def _backlog_page_html(desde):
    return ("""<!doctype html><meta charset=utf-8><title>Reproceso backlog bot</title>
<body style="font-family:system-ui;background:#0b1220;color:#e5edf7;padding:24px;max-width:760px;margin:auto">
<h2>&#129302; Responder backlog del bot</h2>
<p>Corte: desde <b>__D__</b> de hoy hasta ahora (hora Argentina). Solo agarra chats cuyo <b>&uacute;ltimo mensaje es entrante y sigue sin contestar</b>. Cada chat se intenta una sola vez.</p>
<button id=go style="background:#2563eb;color:#fff;border:0;padding:11px 20px;border-radius:9px;font-size:15px;font-weight:700;cursor:pointer">&#9654;&#65039; Empezar</button>
<div id=stat style="margin-top:16px;font-size:15px"></div>
<pre id=log style="margin-top:12px;background:#111c2b;padding:12px;border-radius:8px;max-height:52vh;overflow:auto;font-size:12px;white-space:pre-wrap"></pre>
<script>
var T={p:0,r:0,e:0,f:0,n:0};
var desde="__D__";
function line(s){var l=document.getElementById('log');l.textContent+=s+"\\n";l.scrollTop=l.scrollHeight;}
function stat(x){document.getElementById('stat').innerHTML="Procesados <b>"+T.p+"</b> &middot; &#9989; respondidos <b>"+T.r+"</b> &middot; derivados "+T.e+" &middot; sin respuesta "+T.n+" &middot; fall&oacute; env&iacute;o "+T.f+(x?(" &middot; "+x):"");}
function batch(){
  fetch('/wa-bot-backlog?run=1&n=5&desde='+encodeURIComponent(desde)).then(function(r){return r.json();}).then(function(j){
    if(!j.ok){line("ERROR: "+(j.msg||'?'));document.getElementById('go').disabled=false;return;}
    T.p+=j.procesados_ahora;T.r+=j.respondidos;T.e+=j.escalados;T.f+=j.fallo_envio;T.n+=j.sin_responder;
    (j.detalle||[]).forEach(function(d){line((d.estado||'')+"  "+d.wid+(d.nota?("  \\u2014 "+d.nota):""));});
    stat("quedan "+j.restantes);
    if(j.procesados_ahora>0 && j.restantes>0){ setTimeout(batch,400); }
    else { stat("LISTO \\u2713"); line("\\u2500\\u2500 FIN \\u2500\\u2500"); document.getElementById('go').disabled=false; }
  }).catch(function(e){line("ERROR red: "+e);document.getElementById('go').disabled=false;});
}
document.getElementById('go').onclick=function(){this.disabled=true;T={p:0,r:0,e:0,f:0,n:0};document.getElementById('log').textContent='';stat('arrancando\\u2026');batch();};
</script></body>""").replace("__D__", desde)


@app.route("/wa-bot-backlog", methods=["GET", "POST"])
def wa_bot_backlog():
    """TEMP: reprocesa el backlog de chats sin contestar desde una hora de corte (default 19:00 hoy).
    Destraba el anti-duplicado y corre el cerebro para que responda. Login-gated. Batches de a n."""
    email = _user_actual()
    desde = (request.values.get("desde") or "19:00").strip()
    if not request.values.get("run"):
        if not email:
            return _backlog_page_html(desde).replace("Empezar", "Logueate en RealProfit primero")
        return _backlog_page_html(desde)
    if not email:
        return jsonify({"ok": False, "msg": "sin sesión"})
    conf = _wa_conf(email) or {}
    if not conf.get("bot"):
        return jsonify({"ok": False, "msg": "el bot está apagado para esta cuenta"})
    try:
        hh, mm = [int(x) for x in desde.split(":")[:2]]
    except Exception:
        hh, mm = 19, 0
    hoy = (_dt.datetime.utcnow() - _dt.timedelta(hours=3)).strftime("%Y-%m-%d")
    cutoff = "%s %02d:%02d:00" % (hoy, hh, mm)
    try:
        n = max(1, min(int(request.values.get("n") or 5), 12))
    except Exception:
        n = 5
    chats = _wa_chats_all()
    convs = (chats.get(email) or {})

    def _cands():
        out = []
        for wid, conv in convs.items():
            msgs = conv.get("messages") or []
            if not msgs:
                continue
            last = msgs[-1]
            if last.get("dir") != "in":
                continue
            if (last.get("ts") or "") < cutoff:
                continue
            if conv.get("bot_backlog_seen") == (last.get("id") or ""):
                continue
            out.append((last.get("ts") or "", wid, last.get("id") or ""))
        out.sort()
        return out

    cands = _cands()
    total_pend = len(cands)
    done = resp = esc = fail = noresp = 0
    detalle = []
    import time as _t
    for ts, wid, mid in cands[:n]:
        conv = convs.get(wid)
        if not conv:
            continue
        conv["bot_backlog_seen"] = mid          # ya lo intenté (evita loop infinito)
        conv.pop("bot_last_in", None)           # destraba el anti-duplicado del bot
        antes = len(conv.get("messages") or [])
        try:
            _wa_bot_run(email, conf, wid, chats, canal="web")
        except Exception as e:
            fail += 1
            detalle.append({"wid": wid, "estado": "error", "nota": str(e)[:80]})
            continue
        done += 1
        m2 = (convs.get(wid) or {}).get("messages") or []
        if len(m2) > antes and m2[-1].get("by") == "bot":
            resp += 1
            detalle.append({"wid": wid, "estado": "respondido"})
        else:
            nota = (convs.get(wid) or {}).get("bot_nota", "") or ""
            if "deriv" in nota:
                esc += 1
            elif "envío" in nota or "envio" in nota:
                fail += 1
            else:
                noresp += 1
            detalle.append({"wid": wid, "estado": "sin respuesta", "nota": nota[:90]})
        _t.sleep(0.15)
    _wa_save_chats(chats)
    restantes = max(0, total_pend - done)
    return jsonify({"ok": True, "cutoff": cutoff, "procesados_ahora": done, "respondidos": resp,
                    "escalados": esc, "fallo_envio": fail, "sin_responder": noresp,
                    "restantes": restantes, "detalle": detalle})


def _bot_extra_instr(c):
    """Instrucciones del dueño + los EJEMPLOS aprendidos de chats reales (si cargó alguno). Es lo que
    ve el cerebro además del rol base. Se lo pasamos como extra_instr en cada decisión."""
    instr = (c or {}).get("bot_instr", "") or ""
    ej = (c or {}).get("bot_ejemplos", "") or ""
    if ej.strip():
        instr = (instr + "\n\n# CÓMO RESPONDE EL DUEÑO EN LA REALIDAD (aprendido de chats humanos: tono, "
                 "respuestas típicas y sobre todo QUÉ NO responde solo → escala). Imitá este estilo:\n" + ej.strip())
    return instr


def _wa_aprender_pares(text):
    """Parsea un export de WhatsApp (formato 'CHAT n/N' + '[fecha hora] Quien: msg') y saca los pares
    (mensaje del cliente → respuesta del dueño 'Yo'). Descarta multimedia/notificaciones/base64 y las
    respuestas de PEDIDO PUNTUAL (seguimiento/tracking/reclamo) porque esas las maneja un humano."""
    import re as _re
    SKIP = ("[notificacion", "[imagen]", "[audio", "[documento", "[sticker]", "[llamada]", "[album]",
            "[mensaje eliminado]", "[evento", "[protocol]", "[mensaje interactivo]")
    hdr = _re.compile(r"^\[(\d{2}/\d{2}/\d{4}) (\d{1,2}:\d{2})\]\s+(.+?):\s?(.*)$")
    chatsep = _re.compile(r"^CHAT \d+/\d+:")

    def _malo(t):
        tl = (t or "").lower()
        if any(s in tl for s in SKIP):
            return True
        # base64 / blobs (corridas largas sin espacios) o vacío
        if not t or len(t) < 2:
            return True
        for tok in t.split():
            if len(tok) > 45:
                return True
        return False

    def _es_pedido(t):
        tl = (t or "").lower()
        return ("andreani.com" in tl or "seguimiento" in tl or "reclamo" in tl
                or bool(_re.search(r"\d{10,}", t)))

    chats, cur, speaker, buf = [], [], None, []

    def _flush():
        nonlocal speaker, buf
        if speaker is not None:
            cur.append((speaker, "\n".join(buf).strip()))
        speaker, buf = None, []

    def _flushchat():
        nonlocal cur
        _flush()
        if cur:
            chats.append(cur)
        cur = []

    for ln in (text or "").splitlines():
        s = ln.strip()
        if chatsep.match(s):
            _flushchat(); continue
        if s.startswith("=========="):
            continue
        m = hdr.match(ln)
        if m:
            _flush()
            speaker = "yo" if m.group(3).strip().lower() == "yo" else "cli"
            buf = [m.group(4)]
        elif speaker is not None:
            buf.append(ln)
    _flushchat()

    pares, vistos = [], set()
    for chat in chats:
        i, n = 0, len(chat)
        while i < n:
            if chat[i][0] == "cli":
                q = [chat[i][1]]; j = i + 1
                while j < n and chat[j][0] == "cli":
                    q.append(chat[j][1]); j += 1
                a = []
                while j < n and chat[j][0] == "yo":
                    a.append(chat[j][1]); j += 1
                if a:
                    qt = " ".join(x for x in q if x).strip()
                    at = "\n".join(x for x in a if x).strip()
                    if qt and at and not _malo(qt) and not _malo(at) and not _es_pedido(at):
                        key = _re.sub(r"\s+", " ", at.lower())[:80]
                        if key not in vistos:
                            vistos.add(key)
                            pares.append((qt[:300], at[:700]))
                i = j
            else:
                i += 1
    return pares


@app.post("/wa-bot-aprender")
def wa_bot_aprender():
    """Sube un export de chats de WhatsApp (.txt) → el bot APRENDE tu tono, tus respuestas típicas y qué
    escalás. Destila los pares reales con el mismo cerebro (Claude) y lo guarda por cuenta."""
    email = _user_actual()
    if not email:
        return jsonify({"ok": False, "msg": "sin sesión"})
    toks = _wa_tokens()
    c = toks.get(email)
    if not c:
        return jsonify({"ok": False, "msg": "WhatsApp no conectado"})
    f = request.files.get("file") or (next(iter(request.files.values())) if request.files else None)
    if not f:
        return jsonify({"ok": False, "msg": "subí el .txt de chats"})
    try:
        raw = f.read()
        text = raw.decode("utf-8", "ignore") if isinstance(raw, (bytes, bytearray)) else str(raw)
    except Exception as e:
        return jsonify({"ok": False, "msg": "no pude leer el archivo (%s)" % str(e)[:80]})
    pares = _wa_aprender_pares(text)
    if not pares:
        return jsonify({"ok": False, "msg": "no encontré charlas con respuestas tuyas en ese archivo"})
    try:
        import agente_ia
    except Exception as e:
        return jsonify({"ok": False, "msg": "cerebro no disponible: " + str(e)[:80]})
    if not agente_ia.disponible():
        return jsonify({"ok": False, "msg": "Falta ANTHROPIC_API_KEY en el servidor"})
    # armo una muestra (deduplicada, acotada) para no reventar el contexto
    muestra = pares[:180]
    cuerpo = "\n\n".join("CLIENTE: %s\nDUEÑO: %s" % (q, a) for q, a in muestra)
    sistema = (
        "Sos un analista de atención al cliente. Abajo hay pares REALES de WhatsApp: lo que preguntó un "
        "cliente y cómo respondió el DUEÑO de la tienda. Resumí, EN ARGENTINO y SOLO con lo que aparece "
        "(no inventes precios, links ni datos), en máximo ~3500 caracteres y con este formato exacto:\n"
        "## PREGUNTAS FRECUENTES\n- <pregunta>: <mejor respuesta corta, en el tono del dueño>\n"
        "## EJEMPLOS DE TONO (8, textuales)\nCLIENTE: ...\nDUEÑO: ...\n"
        "## NO RESPONDER SOLO (escalar a humano)\n- <situaciones donde el dueño deriva: pedidos puntuales, "
        "'no me llegó', seguimiento, reclamos, comprobantes, cancelaciones, direcciones>\n"
        "Sé fiel al estilo real del dueño (saludos, muletillas, cómo maneja objeciones)."
    )
    resumen = agente_ia.chat([{"role": "user", "content": cuerpo}], sistema, max_tokens=2200)
    resumen = (resumen or "").strip()[:6000]
    if not resumen or len(resumen) < 40:
        return jsonify({"ok": False, "msg": "no pude destilar los chats, probá de nuevo"})
    c["bot_ejemplos"] = resumen
    c["bot_ejemplos_n"] = len(pares)
    _wa_save_tokens(toks)
    return jsonify({"ok": True, "pares": len(pares), "usados": len(muestra), "resumen": resumen})


@app.post("/wa-web-hook")
def wa_web_hook():
    """Lo llama el servicio de WhatsApp Web (Baileys) por cada mensaje ENTRANTE.
    Guarda el mensaje y, si el bot está en canal web + horario, responde solo. Aislado por cuenta."""
    if not WA_WEB_SECRET or request.headers.get("x-wa-secret") != WA_WEB_SECRET:
        return jsonify({"ok": False}), 403
    d = request.get_json(silent=True) or {}
    email = (d.get("acc") or "").strip()
    # GRUPO DE GASTOS: tiene su propio cerebro y NO pasa por el bot de ventas.
    # Va antes de validar el texto porque en el grupo puede venir solo un audio/foto/PDF.
    if d.get("grupo") and email:
        try:
            if _gastos_hook(email, d):
                return jsonify({"ok": True, "gastos": True})
        except Exception as e:
            return jsonify({"ok": False, "msg": "gastos %s: %s" % (type(e).__name__, str(e)[:120])})
        return jsonify({"ok": True})
    tel = re.sub(r"\D", "", d.get("tel") or d.get("from") or "")
    text = (d.get("text") or "").strip()
    if not email or not tel or not text:
        return jsonify({"ok": False, "msg": "faltan datos"})
    cf = _wa_conf(email)
    if not cf:
        return jsonify({"ok": False, "msg": "cuenta sin WhatsApp"})
    chats = _wa_chats_all()
    conv = chats.setdefault(email, {}).setdefault(tel, {"name": d.get("name") or tel, "messages": []})
    if d.get("name"):
        conv["name"] = d["name"]
    # Guardo el jid EXACTO con el que entró (ej "...@lid"). El bot DEBE responder a este mismo jid,
    # si no WhatsApp lo manda al jid de teléfono (@s.whatsapp.net) y queda un chat DUPLICADO por persona.
    _raw_from = (d.get("from") or "").strip()
    if "@" in _raw_from:
        conv["web_jid"] = _raw_from
    import hashlib as _hl
    # id ÚNICO por mensaje: si el puente manda un id real lo usamos; si no, tel+ts+hash del texto
    # (así el dedup del bot NO bloquea todos los mensajes de un mismo número cuando no viene ts).
    _mid = (d.get("id") or d.get("msgId") or d.get("wamid") or "").strip()
    _inid = _mid or ("web:%s:%s:%s" % (tel, d.get("ts") or "", _hl.sha1(text.encode("utf-8")).hexdigest()[:8]))
    conv["messages"].append({"dir": "in", "text": text, "ts": _wa_now(), "type": "text",
                             "id": _inid, "canal": "web"})
    conv["unread"] = conv.get("unread", 0) + 1
    conv["updated"] = _wa_now()
    _wa_save_chats(chats)
    try:
        _wa_bot_run(email, cf, tel, chats, canal="web")
    except Exception:
        pass
    return jsonify({"ok": True})


# ── Puente con el servicio de WhatsApp Web (Baileys) — todo aislado por email ──
def _wa_web_call(method, path, email, extra=None, timeout=25):
    """Habla con el servicio Node pasando siempre acc=email (aislación). (resp, json|None)."""
    if not (WA_WEB_URL and WA_WEB_SECRET):
        return None, {"ok": False, "msg": "El servicio de WhatsApp Web no está configurado (faltan WA_WEB_URL / WA_WEB_SECRET)."}
    try:
        h = {"x-wa-secret": WA_WEB_SECRET}
        body = dict(extra or {}); body["acc"] = email
        if method == "GET":
            r = requests.get(WA_WEB_URL + path, headers=h, params=body, timeout=timeout)
        else:
            r = requests.post(WA_WEB_URL + path, headers=h, json=body, timeout=timeout)
        return r, (r.json() if r.content else {})
    except Exception as e:
        return None, {"ok": False, "msg": "No se pudo hablar con el servicio Web: " + str(e)[:100]}


